CATS[3].s.push(
{t:"ABOISSO — Santé publique · D.E 2025 (Version C) · QCM",d:"Zone d'entrée, SSP, incidence, ordures ménagères, communication, CHU, épidémiologie, Penta, drogues, tuberculose",qs:[
M("Parmi les tâches suivantes, indiquez celle qui se déroule dans la zone d'entrée au cours d'une séance de vaccination :",["A. Le pointage sur les fiches","B. La vérification des carnets et des rendez-vous","C. La fixation des rendez-vous"],[1],"Zone d'entrée : accueil et vérification des carnets et des rendez-vous. Le pointage est un enregistrement ; la fixation des rendez-vous se fait à la sortie.",null,"1"),
M("Parmi les propositions suivantes indiquez les deux qui sont des composantes préventives de soins de santé primaires",["A. Vaccination contre les principales maladies infectieuses","B. Approvisionnement suffisant en eau potable et les mesures d'assainissement de base.","C. Education appropriée pour la santé en relation avec les problèmes de santé auxquels la population est confrontée","D. Protection maternelle et infantile y compris la santé de la reproduction et la planification familiale."],[0,3],"Composantes préventives : vaccination, protection maternelle et infantile (y compris SR et PF) et lutte contre les endémies locales. L'éducation pour la santé, la nutrition et l'eau/assainissement sont des composantes promotionnelles. (À vérifier avec ton corrigé.)",null,"2"),
M("Parmi les indicateurs suivants, identifiez celui qui permet d'évaluer la qualité de la prévention d'une maladie.",["A. Le taux d'incidence","B. Le taux de létalité","C. Le taux de mortalité"],[0],"Le taux d'incidence mesure l'apparition de nouveaux cas : il apprécie la qualité de la prévention. La létalité apprécie la qualité de la prise en charge des malades.",null,"3"),
M("Parmi les phases suivantes indiquez les deux qui concernent le traitement des ordures ménagères.",["A. Le stockage","B. Le ramassage","C. L'incinération","D. Le compostage"],[2,3],"Le traitement des ordures ménagères se fait par incinération ou compostage. Le stockage et le ramassage sont les deux autres phases de l'évacuation.",null,"4"),
M("Parmi les propositions suivantes, indiquez celle qui désigne un moyen physique utilisé pour la communication",["A. Le message","B. Le canal","C. Le décodage"],[1],"Le canal est le moyen physique par lequel passe le message (voix, radio, affiche…). Le message est le contenu transmis ; le décodage est l'interprétation faite par le récepteur. (À vérifier avec ton corrigé.)",null,"5"),
M("Parmi les propositions suivantes indiquez celle qui désigne les produits livrables d'un programme ou projet de santé.",["A. Les intrants","B. Les extrants","C. Les effets"],[1],"Les produits livrables sont les extrants (résultats immédiats des activités). Les intrants sont les ressources utilisées ; les effets sont des résultats à plus long terme. (À vérifier avec ton corrigé.)",null,"6"),
M("Parmi les sigles suivants, indiquez celui qui correspond à la nouvelle appellation du CHU",["A. EPHN","B. EPHR","C. EPHD"],[0],"Le CHU est devenu l'EPHN (Établissement Public Hospitalier National).",null,"7"),
M("Parmi les questions suivantes, indiquez les deux qui relèvent de l'épidémiologie analytique",["A. Quelle est la cause ?","B. Quand ?","C. Qui ?","D. Pourquoi ?"],[0,3],"L'épidémiologie analytique cherche les causes : « Quelle est la cause ? » et « Pourquoi ? ». « Quand ? » et « Qui ? » relèvent de l'épidémiologie descriptive.",null,"8"),
M("Parmi les propositions suivantes, indiquez les trois conditions qui rendent un flacon entamé de Penta non utilisable.",["A. Lorsqu'il n'est pas périmé","B. Lorsqu'il a été contaminé","C. Lorsqu'il n'a pas été exposé excessivement au froid ou à la chaleur excessive ;","D. Lorsqu'il a été immergé dans de l'eau","E. Lorsqu'il ne présente aucun trouble ou précipitation","F. Lorsqu'il a sa PCV virée."],[1,3,5],"Un flacon entamé est jeté s'il a été contaminé, immergé dans l'eau ou si sa PCV a atteint le point de rejet.",null,"9"),
M("Parmi les aliments suivants indiquez les trois qui sont des tubercules",["A. Igname","B. Mil","C. Arachide","D. Manioc","E. Maïs","F. Taro"],[0,3,5],"Les tubercules sont l'igname, le manioc et le taro. Le mil et le maïs sont des céréales ; l'arachide est une légumineuse (oléagineux).",null,"10"),
M("Parmi les éléments suivants, indiquez les trois qui ne sont pas tarifés au niveau des ESPC",["A. Les vaccins","B. Les mises en observation","C. Les carnets individuels de santé","D. Les seringues de vaccination","E. Les médicaments essentiels de la PSP","F. Les Tests de dépistage rapide de paludisme"],[0,3,5],"Les vaccins, les seringues de vaccination et les tests de dépistage rapide du paludisme ne sont pas tarifés. Les mises en observation, les carnets et les médicaments essentiels sont tarifés. (À vérifier avec ton corrigé.)",null,"11"),
M("Parmi les problèmes suivants causés par l'abus des drogues, indiquez les trois qui sont d'ordre sanitaire.",["A. L'absentéisme scolaire","B. L'hallucination","C. Les accidents de la voie publique","D. Le délire","E. Le suicide","F. L'asthénie"],[1,3,5],"Problèmes d'ordre sanitaire retenus : hallucination, délire et asthénie (même question corrigée dans le sujet de Daloa). L'absentéisme scolaire et les accidents de la voie publique sont d'ordre social.",null,"12"),
M("Parmi les objectifs suivants, indiquez les trois qui relèvent du niveau périphérique",["A. Augmenter la couverture du TDO à 100% sur l'ensemble du territoire national","B. Améliorer le taux de guérison à 85% des malades dépistés","C. Réduire le taux de perdu de vue à 0%.","D. Dépister au moins 70% des TPMP+","E. Impliquer la communauté dans les activités de lutte contre la tuberculose.","F. Augmenter le taux de dépistage à 80% des malades attendus"],[1,2,5],"Niveau périphérique : guérison à 85 %, perdus de vue à 0 % et dépistage à 80 % des malades attendus (même question corrigée dans le sujet de Daloa).",null,"13"),
M("Parmi les maladies suivantes, indiquez les trois qui sont sous surveillance en Côte d'Ivoire",["A. Le choléra","B. Le paludisme","C. La fièvre hémorragique virale","D. La dracunculose","E. Les infections respiratoires aiguës","F. Les infections urinaires"],[0,2,3],"Maladies sous surveillance retenues : choléra, fièvre hémorragique virale et dracunculose (même question corrigée dans le sujet de Daloa).",null,"14"),
M("Parmi les propositions suivantes, indiquez les deux rôles du comité de gestion en dehors du centre",["A. Faire connaître aux populations les activités menées au centre de santé","B. Faire le contrôle de présence du personnel de santé et de soutien ;","C. Rendre disponible des médicaments essentiels et des vaccins ;","D. Encourager les changements de comportements observés au niveau des différents acteurs et utilisateurs"],[0,3],"En dehors du centre, le COGES fait connaître les activités du centre aux populations et encourage les changements de comportements. Le contrôle de présence et la disponibilité des produits relèvent du fonctionnement du centre.",null,"15"),
M("Parmi les éléments suivants, indiquez les trois qui ne constituent pas des niveaux de perception des besoins de santé",["A. Le niveau des besoins non satisfaits ;","B. Le niveau des besoins latents","C. Le niveau des besoins ressentis","D. Le niveau des besoins satisfaits","E. Le niveau des besoins fondamentaux","F. Le niveau des besoins exprimés"],[0,3,4],"Niveaux de perception : besoins latents, ressentis et exprimés. Les besoins non satisfaits, satisfaits et fondamentaux n'en font pas partie. (À vérifier avec ton corrigé.)",null,"16")
]},
{t:"ABOISSO — Santé publique · D.E 2025 (Version C) · QCD",d:"Rotarix, goitre, stratégie avancée, PCV, mobilisation sociale, monitorage, contre-référence, plaidoyer, épidémiologie",qs:[
D("La perte de l'appétit est l'une des contre-indications de l'administration du Rotarix.",1,"Faux. La perte d'appétit n'est pas une contre-indication du Rotarix.",null,"17"),
D("Le goitre endémique est une maladie causée par l'excès de l'iode dans l'eau de consommation.",1,"Faux. Le goitre endémique est dû à la carence en iode.",null,"18"),
D("Faire la vaccination en stratégie avancée est une solution pour réduire les populations hors de portée.",1,"Faux. Correction : « hors d'accès » (et non « hors de portée »). — Support : L2p38",null,"19"),
D("Le site de vaccination est un lieu choisi pour installer l'équipe de vaccination.",1,"Faux. (Même énoncé corrigé dans le sujet de Korhogo.)",null,"20"),
D("Le début effectif de la mise en œuvre des activités des soins de santé en Côte d'Ivoire a eu lieu en 1991 au district sanitaire de Bouaflé.",1,"Faux. — Support : L1p76 (même énoncé corrigé dans le sujet de Korhogo).",null,"21"),
D("Un enfant âgé de 2 semaines ayant déjà reçu le VPO0, le BCG et sa dose d'hépatite B à la naissance est correctement vacciné.",0,"Vrai. Ce sont les vaccins de la naissance. — Support : L2p38",null,"22"),
D("Les virus et les parasites sont des facteurs déterminant la santé.",0,"Vrai. Les agents biologiques (virus, parasites, bactéries) font partie des facteurs qui déterminent la santé.",null,"23"),
D("La société civile constitue une cible de la mobilisation sociale.",0,"Vrai.",null,"24"),
D("La PCV permet d'apprécier la péremption des vaccins.",1,"Faux. La PCV (pastille de contrôle du vaccin) indique l'exposition cumulée du vaccin à la chaleur ; la péremption est donnée par la date inscrite sur le flacon. (À vérifier avec ton corrigé : la copie photographiée porte « Vrai ».)",null,"25"),
D("La vulnérabilité d'un problème prioritaire de santé se détermine par l'existence de mesures de contrôle efficaces du problème.",0,"Vrai. Un problème est vulnérable quand il existe des mesures efficaces pour le contrôler.",null,"26"),
D("Les différends entre les membres d'une communauté ne constituent pas un obstacle à la participation communautaire.",1,"Faux. Les différends entre membres d'une communauté sont un obstacle à la participation communautaire.",null,"27"),
D("Pour une population de plus de 5000 habitants il faut organiser quatre séances de vaccination par mois.",1,"Faux. Une séance par semaine (4 par mois) correspond à 4 000–7 999 habitants ; au-delà, il faut davantage (8 000–11 999 : 2 séances par semaine). (À vérifier avec ton corrigé.)",null,"28"),
D("Le taux de mortalité maternelle est un indice.",1,"Faux. C'est un rapport : décès maternels / naissances vivantes.",null,"29"),
D("Le monitorage peut être considéré comme un suivi des activités.",0,"Vrai. Le monitorage est un suivi régulier des activités.",null,"30"),
D("Le taux de létalité permet d'évaluer la qualité de la prise en charge des malades.",0,"Vrai. Létalité = décès / malades × 100 : plus elle est élevée, plus la prise en charge est à améliorer.",null,"31"),
D("La contre référence est le retour du patient dans l'ESPC d'origine pour la poursuite de son traitement.",0,"Vrai.",null,"32"),
D("L'insuffisance de supervision dans un centre de santé peut être à l'origine d'un goulot d'étranglement entre la couverture adéquate et la couverture effective.",0,"Vrai. (Même énoncé corrigé dans le sujet Version D.)",null,"33"),
D("L'individu constitue une cible du plaidoyer.",1,"Faux. Le plaidoyer s'adresse aux décideurs et aux leaders (autorités politiques, administratives, leaders d'opinion), pas à l'individu.",null,"34"),
D("L'ébullition a pour inconvénient de faire perdre à l'eau les gaz dissouts.",0,"Vrai. L'ébullition tue les germes mais fait perdre à l'eau ses gaz dissous (goût fade). (À vérifier avec ton corrigé : la copie photographiée porte « Faux ».)",null,"35"),
D("Les doses jetées avec les flacons de vaccins reconstitués en fin de séance sont des doses gaspillées.",0,"Vrai. Les doses jetées avec les flacons ouverts non utilisés sont des doses gaspillées.",null,"36"),
D("En matière de vaccination, l'intervalle maximal n'existe pas.",0,"Vrai. Il existe un intervalle minimal entre deux doses, mais pas d'intervalle maximal : on ne recommence pas la série de vaccins.",null,"37"),
D("L'épidémiologique descriptive répond à la question : Combien ?",0,"Vrai. L'épidémiologie descriptive répond aux questions : quand, où, qui, combien (L1p81). (À vérifier avec ton corrigé : la copie photographiée porte « Faux ».)",null,"38"),
D("Le génocide est une catastrophe naturelle.",1,"Faux. Le génocide est une catastrophe d'origine humaine.",null,"39"),
D("Le non-respect de la politique du flacon entamé est un facteur évitable de perte de vaccins.",0,"Vrai.",null,"40")
]},
{t:"ABOISSO — Santé publique · D.E 2025 (Version C) · Étude de cas : centre de santé rural de Gorouo",d:"SSP à renforcer, lutte antivectorielle, population totale et moyenne, monitorage (extrait : pages 5 à 8)",qs:[
M("A partir du texte, indiquez les composantes de soins de santé primaires qu'il faut renforcer pour améliorer la santé des populations de l'aire sanitaire de Gorouo.",["A. Education appropriée pour la santé en relation avec les problèmes de santé auxquels la population est confrontée.","B. Promotion de bonnes conditions alimentaires et nutritionnelles.","C. Approvisionnement suffisant en eau saine ou potable et des mesures d'assainissement de base.","D. Vaccination contre les principales maladies infectieuses.","E. Prévention et la lutte contre les endémies locales.","F. Protection maternelle et infantile, y compris la santé de la reproduction et la planification familiale."],[1,2,4,5],"Les ordures mal éliminées relèvent de l'assainissement (C) ; les moustiques de la lutte contre les endémies locales (E) ; les grossesses trop rapprochées de la PMI/PF (F) ; la malnutrition des enfants de la nutrition (B).","<b>ETUDE DE CAS</b><br><i>Consignes : les résultats des calculs comportant des virgules sont à arrondir à la fin de chaque calcul au quart supérieur quel que soit la valeur des chiffres après la virgule. Les arrondissements ne concernent pas les pourcentages.</i><br>Le centre de santé rural de <b>Gorouo</b> a été officiellement ouvert le 17 Avril 2024. Vous y avez pris service le 18 Avril 2024. La population totale de l'aire sanitaire de ce centre de santé rural est de <b>25000 habitants</b> au 01/01/2024, avec un taux d'accroissement annuel constant de <b>2%</b>. Les naissances enregistrées au cours de l'année 2024 sont 250 dont 20 mort-nés.<br>Après une étude du milieu vous constatez que les ordures ménagères ne sont pas correctement éliminées par les populations de l'aire sanitaire et l'on observe une forte prolifération des moustiques dans la localité. Par ailleurs, les femmes contractent des grossesses trop rapprochées et l'on observe de nombreux cas de malnutrition chez les enfants.<br>Au cours du second monitorage des activités du centre de santé rural de Gorouo de l'année 2024, les informations suivantes ont été notées :<br>- le montant à la banque après les mouvements bancaires, la somme à budgétiser et le coût des actes de santé sont respectivement estimés à 1000000 FCFA, 600000 FCFA et 350000 FCFA ;<br>- le montant du salaire du personnel journalier du centre de santé rural de Gorouo estimé à 500000 FCFA.","41"),
M("Parmi les propositions suivantes indiquez les deux mesures de lutte contre les moustiques adultes en vue de prévenir le paludisme.",["A. Vider et enlever tous les récipients pouvant contenir de l'eau","B. Dormir sous une moustiquaire imprégnée d'insecticide","C. Pulvériser l'intérieur des maisons d'insecticides","D. Drainer et combler les flaques d'eau et autres endroits ou l'eau peut stagner"],[1,2],"Contre les moustiques adultes : moustiquaire imprégnée et pulvérisation intradomiciliaire. Vider les récipients et drainer les flaques sont des mesures contre les larves.",null,"42"),
M("Quelle est la population totale de l'aire sanitaire du Centre de santé rural de Gorouo au 31/12/2024 ?",["A. 25000","B. 25300","C. 25500"],[2],"Population au 31/12/2024 = 25 000 × 1,02 = 25 500.",null,"43"),
M("Quelle est la population moyenne de l'aire sanitaire du Centre de santé rural de Gorouo en 2024 ?",["A. 25250","B. 25150","C. 25100"],[0],"Population moyenne = (25 000 + 25 500) / 2 = 25 250.",null,"44"),
M("Quelle est la période dont les activités feront l'objet du premier monitorage de l'année 2025 ?",["A. Juin 2024 à Novembre 2024","B. Décembre 2023 à Juin 2024","C. Décembre 2024 à Mai 2025"],[2],"Un monitorage porte sur six mois : le second monitorage de 2024 couvre juin–novembre 2024, donc le premier de 2025 couvre décembre 2024–mai 2025.",null,"52")
]}
);

// ===== ABOISSO · D.E 2025 Médecine Version D (photos fournies) =====
CATS[1].s.push(
{t:"ABOISSO — Médecine · D.E 2025 (Version D) · Études de cas N°1 et N°2",d:"Fièvre typhoïde (M. Konan), IMC, hépatite B et transfusion (M. Zoro)",qs:[
M("A partir des données du texte, indiquez parmi les maladies suivantes celle dont souffre Monsieur Konan",["A. Paludisme","B. Fièvre typhoïde","C. Méningite"],[1],"Céphalées, fièvre à 40 °C avec pouls à 70/mn (dissociation pouls-température), selles fétides, anorexie, vertiges, insomnie et goutte épaisse négative : fièvre typhoïde.","<b>ETUDE DE CAS N°1</b><br>Monsieur Konan se présente en consultation chez vous en présentant des céphalées, des selles fétides, une fièvre et une anorexie. Après deux jours de traitement, vous lui demandez une goutte épaisse dont le résultat est négatif. Par ailleurs, il vous précise au troisième jour qu'en plus des premiers signes évoqués, il ressent des vertiges et éprouve des difficultés à s'endormir.<br>A l'examen physique vous notez les constantes suivantes :<br>- température : <b>40°C</b> ;<br>- Pouls : <b>70 pulsations/mn</b> ;<br>- Tension artérielle : <b>120/70 mmHg</b> ;<br>- Poids : <b>70 kg</b> ;<br>- Taille : <b>1,75 m</b>.<br><i>Consignes : en vous servant des informations du texte ci-dessus répondez aux questions suivantes.</i>","1"),
M("Parmi les germes suivants indiquez celui qui est responsable de la maladie de Monsieur Konan",["A. Le Méningocoque","B. La Salmonelle","C. Le Plasmodium"],[1],"La fièvre typhoïde est due à Salmonella Typhi (bacille d'Eberth).",null,"2"),
M("Quel est l'examen biologique pouvant vous permettre de poser le diagnostic fiable de Monsieur Konan ?",["A. La Coproculture","B. La numération formule sanguine","C. La ponction lombaire"],[0],"Le diagnostic de certitude repose sur l'isolement du germe : coproculture (ou hémoculture). La NFS n'est pas spécifique ; la ponction lombaire sert au diagnostic de méningite.",null,"3"),
M("Quel est l'indice de masse corporelle de Monsieur Konan ?",["A. 22,85","B. 28,14","C. 30,14"],[0],"IMC = poids / taille² = 70 / (1,75)² = 70 / 3,0625 ≈ 22,85.",null,"4"),
M("Que peut-on dire du poids de Monsieur Konan ?",["A. Poids insuffisant","B. Poids normal","C. Surpoids"],[1],"Un IMC de 22,85 est compris entre 18,5 et 24,9 : poids (corpulence) normal. (La copie photographiée porte « poids insuffisant » : à vérifier avec ton corrigé.)",null,"5"),
M("Parmi les signes suivants, indiquez les deux qui caractérisent la phase pré ictérique de l'hépatite virale.",["A. Arthralgie","B. Diarrhée","C. Vertige","D. Asthénie"],[0,3],"La phase pré ictérique associe asthénie, anorexie, nausées, fièvre modérée et arthralgies. (À vérifier avec ton corrigé.)","<b>ETUDE DE CAS N°2</b><br>Le 23 mars 2025, vous recevez en consultation Monsieur <b>Zoro</b>, âgé de 43 ans, conducteur de tracteur à la SUCAFCI, en phase pré ictérique d'une hépatite virale. Les investigations cliniques et paracliniques entreprises révèlent qu'il s'agit de l'hépatite B, contractée lors d'une transfusion sanguine. Son taux d'hémoglobine se chiffre à <b>5 g/dl</b>, son poids à <b>55 kg</b> et son groupe sanguin est <b>B positif</b>.<br><i>Consignes : en vous servant des informations du texte ci-dessus répondez aux questions suivantes.</i>","6"),
M("Parmi les groupes sanguins suivants, indiquez les deux dont le sang peut être transfusé à Monsieur Zoro.",["A. O négatif","B. AB négatif","C. AB positif","D. B négatif"],[0,3],"Un receveur B positif peut recevoir du sang O (négatif ou positif) et B (négatif ou positif). Parmi les propositions : O négatif et B négatif.",null,"7"),
M("Parmi les quantités suivantes de sang, indiquez celle qui correspond au volume sanguin à transfuser à Monsieur Zoro pour corriger l'anémie.",["A. 3040 ml","B. 2340 ml","C. 4320 ml"],[1],"Volume = (THb attendu − THb du patient) × 6 × poids. Avec un THb attendu voisin de 12 g/dl : (12 − 5) × 6 × 55 ≈ 2 310 ml, la valeur la plus proche étant 2 340 ml. (À vérifier avec ton corrigé : le THb attendu n'est pas précisé sur la copie.)",null,"8"),
M("Parmi les précautions suivantes, laquelle préconisez-vous avant la vaccination des membres de la famille de Monsieur Zoro contre l'hépatite B.",["A. Assurer l'hygiène de vie et environnementale","B. Faire une sérothérapie","C. Faire un dépistage de l'hépatite B chez les membres de la famille de Monsieur Zoro."],[2],"Avant de vacciner contre l'hépatite B, on dépiste les membres de la famille : la vaccination ne concerne que les sujets non infectés.",null,"9")
]},
{t:"ABOISSO — Médecine · D.E 2025 (Version D) · QCM",d:"Fièvre typhoïde, schistosomiase, dengue, ascite, ARV, œdèmes, hépatite A, paludisme, Köplick, IMC, pian, rage",qs:[
M("Parmi les propositions suivantes, indiquez les deux signes qui caractérisent le premier septénaire de la fièvre typhoïde",["A. Fièvre en plateau","B. Épistaxis","C. Fièvre à oscillations ascendantes","D. Tuphos"],[1,2],"Premier septénaire : fièvre à oscillations ascendantes (en marches d'escalier), céphalées, épistaxis. La fièvre en plateau et le tuphos caractérisent le deuxième septénaire.",null,"10"),
M("Parmi les propositions suivantes, indiquez le signe dominant observé chez un malade pendant la phase d'incubation de la Schistosomiase",["A. Une dermatite cercarienne","B. Une hématurie","C. Une fièvre"],[0],"La pénétration des cercaires dans la peau provoque la dermatite cercarienne. L'hématurie est un signe de la phase d'état.",null,"11"),
M("Parmi les propositions suivantes, indiquez celle qui correspond au cycle de vie du moustique hématophage qui transmet le virus de la dengue.",["A. Une phase terrestre et une phase aquatique","B. Une phase terrestre, une phase aquatique et une phase aérienne","C. Une phase aquatique et une phase aérienne"],[2],"Le moustique a une phase aquatique (œuf, larve, nymphe) et une phase aérienne (adulte). (À vérifier avec ton corrigé : la copie photographiée porte A.)",null,"12"),
M("Parmi les propositions suivantes, indiquez celle qui correspond au site de la ponction d'ascite.",["A. La fosse iliaque droite","B. L'hypochondre droit","C. La fosse iliaque gauche"],[2],"La ponction d'ascite se fait dans la fosse iliaque gauche, au tiers externe de la ligne reliant l'ombilic à l'épine iliaque antéro-supérieure.",null,"13"),
M("Parmi les propositions suivantes, indiquez celle qui correspond à la définition d'un patient naïf aux ARV",["A. Un patient n'ayant jamais pris d'antirétroviral","B. Un patient sous traitement antirétroviral","C. Un patient ayant arrêté son traitement antirétroviral"],[0],"Un patient naïf aux ARV n'a jamais reçu d'antirétroviraux.",null,"14"),
M("Parmi les propositions suivantes, indiquez les deux qui caractérisent les œdèmes des membres inférieurs d'origine cardiaque",["A. Œdèmes symétriques","B. Œdèmes unilatérales","C. Œdèmes douloureux","D. Œdèmes prenant le godet"],[0,3],"Les œdèmes cardiaques sont bilatéraux, symétriques, indolores, blancs et prennent le godet. Un œdème unilatéral et douloureux évoque plutôt une phlébite.",null,"15"),
M("Parmi les propositions suivantes, indiquez la voie de transmission du virus de l'hépatite A",["A. Voie sexuelle","B. Voie sanguine","C. Voie digestive"],[2],"L'hépatite A se transmet par voie digestive (fécale-orale : eau et aliments souillés, mains sales).",null,"16"),
M("Parmi les éléments suivants indiquez l'agent pathogène du paludisme.",["A. L'anophèle femelle","B. Le moustique du genre Aedes","C. Le Plasmodium"],[2],"L'agent pathogène est le Plasmodium (parasite). L'anophèle femelle est le vecteur ; l'Aedes transmet la dengue.",null,"17"),
M("Parmi les maladies suivantes indiquez celle dont le diagnostic est posé en recherchant le signe de Köplik",["A. La méningite purulente","B. Le tétanos","C. La rougeole"],[2],"Le signe de Köplik (petites taches blanches sur la face interne des joues) est évocateur de la rougeole.",null,"18"),
M("Parmi les états suivants, indiquez celui qui correspond à une personne de sexe masculin ayant un indice de masse corporelle égal à 18,35",["A. Obésité","B. Corpulence normale","C. Maigreur"],[2],"Un IMC inférieur à 18,5 correspond à la maigreur.",null,"19"),
M("Parmi les maladies infectieuses suivantes, indiquez les deux qui ne sont pas virales",["A. La Diphtérie","B. Les oreillons","C. La Rougeole","D. Le Tétanos"],[0,3],"La diphtérie et le tétanos sont des maladies bactériennes ; les oreillons et la rougeole sont virales.",null,"20"),
M("Parmi les éléments suivants, indiquez les deux qui sont des constituants de l'urine",["A. Le glucose","B. L'Urée","C. Le Chlore","D. L'albumine"],[1,2],"L'urine normale contient de l'urée et des chlorures. Le glucose et l'albumine sont absents de l'urine normale (leur présence est pathologique).",null,"21"),
M("Parmi les vecteurs suivants, indiquez celui qui est responsable de la transmission de l'onchocercose.",["A. La glossine","B. La mouche tsé-tsé","C. La simulie"],[2],"L'onchocercose est transmise par la simulie. La glossine (mouche tsé-tsé) transmet la trypanosomiase.",null,"22"),
M("Parmi les propositions suivantes, indiquez celle qui correspond au type d'hématurie observée au cours de la bilharziose urogénitale.",["A. L'hématurie initiale","B. L'hématurie totale","C. L'hématurie terminale"],[2],"Dans la bilharziose urogénitale, l'hématurie est terminale (sang en fin de miction).",null,"23"),
M("Parmi les vers suivants, indiquez les deux qui infestent l'organisme humain par voie orale.",["A. L'Oxyure","B. L'Ascaris","C. L'Ankylostome","D. Le Schistosome"],[0,1],"L'oxyure et l'ascaris s'ingèrent (mains sales, aliments souillés). L'ankylostome et le schistosome pénètrent par la peau.",null,"24"),
M("Parmi les éléments suivants, indiquez celui qui correspond à l'appellation de la destruction totale du massif facial pendant la phase tertiaire du pian.",["A. Pian-crabe","B. Noma","C. Gangosa"],[2],"La destruction du massif facial au stade tertiaire du pian s'appelle la gangosa. Le pian-crabe est une kératodermie palmo-plantaire ; le noma est une gangrène de la face.",null,"25"),
M("Parmi les propositions suivantes, indiquez les deux signes qui caractérisent la forme « furieuse » de la rage.",["A. Des troubles du comportement","B. Une hydrophobie","C. Une éruption cutanée","D. Une euphorie"],[0,1],"La rage furieuse associe troubles du comportement (agitation) et hydrophobie (spasmes à la vue ou au contact de l'eau).",null,"26"),
M("Parmi les propositions suivantes, indiquez celui qui correspond à une réaction réflexe involontaire observée lorsqu'on fléchit passivement la nuque du patient allongé sur le dos.",["A. Le signe de Kernig","B. Le signe de Köplick","C. Le signe de Brudzinski"],[2],"Le signe de Brudzinski est la flexion involontaire des genoux à la flexion passive de la nuque (méningite). Le signe de Kernig se recherche en fléchissant la jambe sur la cuisse.",null,"27")
]},
{t:"ABOISSO — Médecine · D.E 2025 (Version D) · QCD",d:"Coronaropathies, dengue, VIH, oxyurose, ankylostomiase, tuberculose, typhoïde, rougeole, tétanos, lèpre, RAA, diabète",qs:[
D("Les coronaropathies sont aussi appelées cardiopathies ischémiques.",0,"Vrai.",null,"28"),
D("La lithiase urinaire est une complication de la lithiase biliaire.",1,"Faux. Ce sont deux maladies différentes.",null,"29"),
D("Chez le sujet atteint de dengue fébrile on observe une thrombocytopénie et une leucopénie.",0,"Vrai. Baisse des plaquettes et des globules blancs, à surveiller (risque hémorragique).",null,"30"),
D("Au cours de l'infection à VIH, l'approche de prise en charge qui implique un laboratoire est l'approche étiologique.",0,"Vrai. L'approche étiologique repose sur l'identification de l'agent par le laboratoire ; l'approche syndromique s'en passe. (À vérifier avec ton corrigé : la copie photographiée porte « V » corrigé en « F ».)",null,"31"),
D("La prévention primaire des infections sexuellement transmissibles ne permet pas de prévenir la survenue du VIH.",1,"Faux. Préservatif et changement de comportement préviennent les IST et le VIH. (À vérifier avec ton corrigé : la copie photographiée porte « Vrai ».)",null,"32"),
D("Le prurit anal diurne intensif est un signe évocateur de l'oxyurose.",1,"Faux. Le prurit anal de l'oxyurose est surtout vespéral et nocturne. (À vérifier avec ton corrigé : la copie photographiée porte « Vrai ».)",null,"33"),
D("L'ankylostomiase est une infection parasitaire qui ne peut pas entrainer d'anémie chez le malade.",1,"Faux. L'ankylostome se nourrit de sang : il provoque une anémie.",null,"34"),
D("La phase initiale du traitement antituberculeux standard dure 4mois.",1,"Faux. La phase initiale (intensive) dure 2 mois.",null,"35"),
D("L'énurésie est une miction incontrôlée qui survient au cours du sommeil.",0,"Vrai.",null,"36"),
D("Le solde hydrique est la somme des entrées et des sorties lors d'une hydratation vasculaire.",1,"Faux. Le solde hydrique est la différence entre les entrées et les sorties.",null,"37"),
D("Le germe responsable de la fièvre typhoïde est le Bacille d'Eberth.",0,"Vrai. Salmonella Typhi.",null,"38"),
D("La chronologie de l'apparition des boutons au cours de la rougeole évolue de la tête aux pieds.",0,"Vrai. L'éruption commence derrière les oreilles et au visage, puis gagne le tronc et les membres.",null,"39"),
D("Le tétanos est une toxi-infection contagieuse et immunisante.",1,"Faux. Correction : « non contagieuse et non immunisante ». — Support : L1p109 (Doc de maladie infectieuse)",null,"40"),
D("La gravité de la lèpre réside dans l'atteinte des nerfs profonds.",1,"Faux. La gravité de la lèpre réside dans l'atteinte des nerfs périphériques (superficiels). (À vérifier avec ton corrigé : la copie photographiée porte « Vrai ».)",null,"41"),
D("Le rhumatisme articulaire aigu est provoqué par un streptocoque hémolytique du groupe A.",0,"Vrai. Streptocoque bêta-hémolytique du groupe A.",null,"42"),
D("Les exotoxines sont des toxines secrétées par les bactéries vers l'intérieur et provoquant des lésions à distance.",1,"Faux. Les exotoxines sont sécrétées vers l'extérieur de la bactérie.",null,"43"),
D("La virulence d'un germe est la propriété pour celui-ci de fabriquer des toxines.",1,"Faux. La virulence est le degré du pouvoir pathogène ; fabriquer des toxines est le pouvoir toxinogène.",null,"44"),
D("L'air peut être le réservoir d'un germe anaérobique.",1,"Faux. Un germe anaérobie vit à l'abri de l'air (sol, tube digestif). (À vérifier avec ton corrigé : la copie photographiée porte « Vrai ».)",null,"45"),
D("L'auto-infection s'observe avec les porteurs sains.",0,"Vrai. Un porteur sain peut s'infecter avec ses propres germes. (À vérifier avec ton corrigé.)",null,"46"),
D("Les maladies cérébro-vasculaires touchent les vaisseaux sanguins qui alimentent le muscle cardiaque.",1,"Faux. Correction : « cerveau → AVC » ; les vaisseaux du muscle cardiaque sont les coronaires.",null,"47"),
D("Le gonflement articulaire est un signe observé au cours de la cardiopathie rhumatismale.",1,"Faux. La cardiopathie rhumatismale est une atteinte des valves du cœur ; le gonflement articulaire est un signe du rhumatisme articulaire aigu. (À vérifier avec ton corrigé.)",null,"48"),
D("Le test de dépistage rapide est un examen de référence pour établir le diagnostic de paludisme.",1,"Faux. Correction : « certitude » ; l'examen de référence est la goutte épaisse (et le frottis).",null,"49"),
D("Le diabète de type 1 résulte d'une mauvaise utilisation de l'insuline par l'organisme.",1,"Faux. Le diabète de type 1 résulte d'un manque d'insuline (destruction des cellules bêta) ; la mauvaise utilisation de l'insuline caractérise le type 2.",null,"50"),
D("Chez l'adulte le premier test rapide utilisé pour le dépistage du VIH est le détermine.",1,"Faux d'après la copie photographiée. (À vérifier avec ton corrigé : le sujet de MAN donne « Vrai » pour le même énoncé.)",null,"51")
]}
);

// ===== ABOISSO · D.E 2025 Chirurgie Version C (page 5/6) et Pédiatrie 1er sujet Bloc D (photos fournies) =====
CATS[2].s.push(
{t:"ABOISSO — Pédiatrie · D.E 2025 (1er sujet, Bloc D) · QCM",d:"Crise génitale, mère-kangourou, diarrhée, F75, prolactine, diazépam, démarche de soins (JK), vitamine K1, photothérapie, périmètre brachial",qs:[
M("Les signes suivants sont observés au cours de la crise génitale du nouveau-né de sexe féminin sauf un. Cochez l'intrus :",["A. Gonflement des seins","B. Pertes vaginales de sang ou de liquide brun","C. Hydrocèle vaginale","D. Tuméfaction des grandes lèvres et de la vulve"],[2],"La crise génitale du nouveau-né fille associe gonflement des seins, pertes vaginales (blanchâtres ou sanglantes) et tuméfaction de la vulve. L'hydrocèle est un signe du nouveau-né garçon. (À vérifier avec ton corrigé : la copie porte B.)",null,"1"),
M("Les soins Mère-Kangourou réalisés pour prendre en charge le nouveau-né prématuré constituent pour l'agent de santé :",["A. Un rôle délégué","B. Un rôle de collaboration","C. Un rôle de conseils et prévention","D. Un rôle propre"],[3],"Les soins Mère-Kangourou relèvent du rôle propre de l'infirmier.",null,"2"),
M("Parmi les examens para cliniques suivants prescrits chez l'enfant présentant une fièvre aiguë (fièvre évoluant depuis moins d'une semaine) se trouve un intru. Cochez l'intrus",["A. Goutte épaisse et frottis sanguin","B. Intradermoréaction à la tuberculine","C. Protéine C réactive (CRP)","D. Hémogramme (NFS)"],[1],"L'IDR à la tuberculine explore la tuberculose, affection chronique, et non une fièvre aiguë.",null,"3"),
M("KP est né le 20 septembre 2025 à 10h00min à l'EPHD de Kounahiri. Les propositions suivantes sont des gestes de soins à réaliser chez KP entre 10h01min et 11h00min, sauf une. Cochez cette proposition.",["A. Surveiller la température toutes les 15 min","B. Surveiller la respiration","C. Aider la mère à le mettre au sein","D. Prendre les constantes (poids, taille, PC)"],[3],"Pendant la première heure : surveillance de la température et de la respiration, mise au sein. Les mesures (poids, taille, PC) se font après cette première heure.",null,"4"),
M("Les soins propres dans la prise en charge de la diarrhée aiguë chez l'enfant sont les suivants, sauf un. Cochez l'intrus :",["A. Nettoyer l'enfant","B. Aider à alimenter l'enfant","C. Administrer l'antibiotique","D. Surveiller l'enfant"],[2],"Administrer l'antibiotique est un soin délégué (prescrit), pas un soin propre.",null,"5"),
M("Un nourrisson âgé de 19 mois pesant 12 kg est hospitalisé pour une malnutrition aiguë sévère. Je décide de lui administrer du lait thérapeutique F75. La quantité totale de lait thérapeutique F75 à donner sur 24 heures est de :",["A. 1560 ml","B. 1460 ml","C. 1360 ml","D. 1260 ml"],[0],"F75 : 130 ml/kg/jour en l'absence d'œdèmes (100 ml/kg/jour avec œdèmes) : 12 × 130 = 1 560 ml.",null,"6"),
M("Chez ce nourrisson de 19 mois hospitalisé pour malnutrition aiguë sévère, je surveille pendant le traitement les paramètres suivants sauf un. Cochez l'intrus",["A. Taille","B. Poids","C. Œdème","D. Appétit"],[0],"Pendant le traitement on surveille le poids, les œdèmes et l'appétit. La taille se mesure à l'admission, pas au quotidien. (À vérifier avec ton corrigé : la copie porte C.)",null,"7"),
M("La cellule cible au niveau du sein sur laquelle l'hormone prolactine agit pour produire le lait maternel est :",["A. La cellule galactophore","B. La cellule épithéliale","C. La cellule adipeuse","D. La cellule myoépithéliale"],[1],"La prolactine agit sur les cellules épithéliales (lactocytes) des alvéoles pour produire le lait ; l'ocytocine agit sur les cellules myoépithéliales (éjection du lait).",null,"8"),
M("Vous recevez aux urgences pédiatriques un nourrisson âgé de 8 mois pour des convulsions. Il pèse 12 kilogrammes. La dose journalière de Diazépam à ne pas dépasser chez ce nourrisson est de :",["A. 36 mg par jour","B. 40 mg par jour","C. 30 mg par jour","D. 26 mg par jour"],[0],"Diazépam : dose maximale 3 mg/kg/jour : 12 × 3 = 36 mg.",null,"9"),
M("Parmi les propositions suivantes, cochez la proposition qui est utilisée pour surveiller la maturation de l'enfant",["A. La taille","B. La fontanelle","C. Le poids","D. Le périmètre brachial"],[1],"La maturation (ossification) se surveille par la fontanelle (et la dentition). Taille et poids surveillent la croissance.",null,"10"),
M("Un nourrisson de 17 mois est amené en consultation parce qu'il n'a aucune dent dans la bouche. Dans cette situation :",["A. Je recommande de consulter un médecin","B. Je prescris un traitement à base de Fluor","C. Je conseille de revenir dans 1 mois","D. Je conseille de consulter un tradipraticien"],[2],"L'absence de dent n'est préoccupante qu'à partir de 18 mois : à 17 mois on conseille de revenir dans 1 mois. (À vérifier avec ton corrigé : la copie porte B.)",null,"11"),
M("Le poids de naissance normal du nouveau-né à terme est compris entre",["A. 1000 et 1500 grammes","B. 1500 et 2500 grammes","C. 2500 et 4000 grammes","D. 4000 et 5000 grammes"],[2],"Poids de naissance normal : 2 500 à 4 000 g.",null,"12"),
M("Dans la diarrhée aiguë de l'enfant la principale complication à craindre en urgence est",["A. L'anémie sévère","B. La convulsion","C. La déshydratation","D. La dénutrition"],[2],"La déshydratation est la principale complication de la diarrhée aiguë.",null,"13"),
M("Parmi les propositions suivantes le signe clinique retrouvé chez un enfant souffrant de marasme est",["A. Visage arrondi","B. Regard vif","C. Aspect de grand brûlé","D. Œdème au dos du pied"],[1],"Le marasme donne un enfant amaigri au regard vif. Visage arrondi, aspect de grand brûlé et œdèmes sont des signes du kwashiorkor.",null,"14"),
M("Parmi les propositions suivantes la nouvelle acquisition psychomotrice attendue chez un enfant de quatre (4) ans est :",["A. Copier un carré","B. Copier un rond","C. Faire des gribouilles","D. Copier une croix"],[3],"Le rond est copié vers 3 ans, la croix vers 4 ans, le carré vers 5 ans. (À vérifier avec ton corrigé : la copie porte A.)",null,"15"),
M("Parmi les propositions suivantes, le critère de mauvais positionnement au sein au cours de la tétée est :",["A. La bouche du nourrisson est au contact du mamelon","B. La nuque du nourrisson repose sur le pli du coude de la mère","C. L'abdomen du nourrisson est en contact avec celui de la mère","D. Le dos du nourrisson repose sur le bras de la mère"],[3],"Bon positionnement : nuque sur le pli du coude, ventre contre ventre, bouche au contact du mamelon. Le dos qui repose sur le bras est un mauvais positionnement.",null,"16"),
M("La prise pondérale journalière normale, chez un nourrisson à croissance normale est de :",["A. 10 grammes entre 0 et 3 mois","B. 12 grammes entre 3 et 6 mois","C. 15 grammes entre 6 et 9 mois","D. 25 grammes entre 9 et 24 mois"],[2],"Prise de poids journalière : environ 30 g (0–3 mois), 20 g (3–6 mois), 15 g (6–9 mois), 10 g (9–12 mois). (À vérifier avec ton corrigé.)",null,"17"),
M("Parmi les propositions de tranche d'âge suivante, cocher la tranche d'âge où on mesure le poids de l'enfant tous les trois (3) mois :",["A. 25 et 36 mois","B. 13 et 24 mois","C. 4 et 12 mois","D. 0 et 3 mois"],[1],"Pesée mensuelle de 0 à 12 mois, trimestrielle de 13 à 24 mois, puis semestrielle. (À vérifier avec ton corrigé.)",null,"18"),
M("Un nourrisson de 8 mois pesant 8 kilogrammes est admis en urgence pour une diarrhée faite de 5 selles molles et glaireuses par jour. Le nourrisson est agité, réclame à boire, les yeux sont enfoncés et le pli cutané abdominal s'efface lentement. La quantité de SRO à administrer à ce nourrisson pendant les 4 premières heures à l'hôpital est de :",["A. 1000 ml","B. 700 ml","C. 1500 ml","D. 600 ml"],[3],"Déshydratation modérée (plan B) : SRO 75 ml/kg en 4 heures : 8 × 75 = 600 ml.",null,"19"),
M("Après la naissance, la mère met son nouveau-né au sein dans :",["A. L'heure qui suit la naissance","B. Deux heures après la naissance","C. Trois heures après la naissance","D. Quatre heures après la naissance"],[0],"La mise au sein se fait dans l'heure qui suit la naissance.",null,"20"),
M("Le nourrisson JK, sexe féminin, âgé de 16 mois vit avec ses parents à Petit Yapo. JK est sevré depuis l'âge de 15mois et n'est pas à jour dans ses vaccins. Il présente une fièvre et le médecin suspecte une méningite purulente. JK a au total :",["A. Deux données de dépendance","B. Trois données de dépendance","C. Quatre données de dépendance","D. Cinq données de dépendance"],[2],"Données de dépendance : sevrage à 15 mois, vaccins non à jour, fièvre, suspicion de méningite purulente = 4. (À vérifier avec ton corrigé : la copie porte D.)",null,"21"),
M("Le nourrisson JK, sexe féminin, âgé de 16 mois vit avec ses parents à Petit Yapo. JK est sevré depuis l'âge de 15mois et n'est pas à jour dans ses vaccins. Il présente une fièvre et le médecin suspecte une méningite purulente. JK a au total :",["A. Deux données d'indépendance","B. Trois données d'indépendance","C. Quatre données d'indépendance","D. Cinq données d'indépendance"],[2],"Données d'indépendance : identité (JK), sexe féminin, âge de 16 mois, vit avec ses parents à Petit Yapo = 4. (À vérifier avec ton corrigé.)",null,"22"),
M("Le nourrisson JK, sexe féminin, âgé de 16 mois vit avec ses parents à Petit Yapo. JK est sevré depuis l'âge de 15mois et n'est pas à jour dans ses vaccins. Il présente une fièvre et le médecin suspecte une méningite purulente. JK a dans sa réalité personnelle :",["A. 1 données d'indépendance et 3 données de dépendance","B. 0 données d'indépendance et 4 données de dépendance","C. 2 données d'indépendance et 2 données de dépendance","D. 3 données d'indépendance et 3 données de dépendance"],[3],"Réponse retenue d'après les marques de la copie : 3 données d'indépendance (sexe, âge, lieu de vie) et 3 de dépendance (sevrage, vaccins, fièvre). (À vérifier avec ton corrigé.)",null,"23"),
M("L'interprétation des données de dépendance du nourrisson JK révèle les problèmes infirmiers suivants sauf un. Cochez l'intrus :",["A. Apport insuffisant de nutriment","B. Perturbation de la thermorégulation","C. Insuffisance de protection contre les agents infectieux","D. Méningite purulente de l'enfant"],[3],"La méningite purulente est un diagnostic médical, pas un problème infirmier. Sevrage précoce → apport insuffisant de nutriment ; fièvre → perturbation de la thermorégulation ; vaccins non à jour → insuffisance de protection.",null,"24"),
M("La dose de vitamine K1 à administrer chez un nouveau-né pesant 1950 grammes hospitalisé en néonatologie pour maladie hémorragique du nouveau-né est :",["A. 1 mg en intra musculaire","B. 0,5 mg en intramusculaire","C. 5 mg en intraveineuse directe","D. 10 mg en intraveineuse directe"],[3],"En traitement curatif de la maladie hémorragique du nouveau-né : 10 mg de vitamine K1 en intraveineuse. (1 mg en IM est la dose préventive.) (À vérifier avec ton corrigé.)",null,"25"),
M("MM est hospitalisé en pédiatrie pour une infection pulmonaire. Le médecin vous demande de lui administrer par voie parentérale 250 mg d'Amoxicilline. Vous disposez d'un flacon poudre de 500mg et 4ml de solvant pour la dilution de la poudre. La quantité de produit dilué que je prélève pour respecter la dose prescrite par le médecin est :",["A. 3 ml","B. 2 ml","C. 2,5 ml","D. 1 ml"],[1],"500 mg dilués dans 4 ml : 250 mg = la moitié du flacon = 2 ml.",null,"26"),
M("L'eau contenue dans le bac à eau de l'incubateur a pour rôle :",["A. Purifier l'air de l'incubateur","B. Protéger l'incubateur des fourmis","C. Humidifier l'air dans l'incubateur","D. Filtrer l'air dans l'incubateur"],[2],"L'eau du bac sert à humidifier l'air de l'incubateur. (La copie photographiée porte A : à vérifier avec ton corrigé.)",null,"27"),
M("La classe thérapeutique à laquelle appartient la Vitamine K1 est",["A. Antibiotique","B. Antifongique","C. Antihémorragique","D. Antiviraux"],[2],"La vitamine K1 est un antihémorragique.",null,"28"),
M("MM pèse 3000 grammes. Il est hospitalisé en néonatologie pour ictère compliqué et mis sous photothérapie. En situation normale, MM reçois 80ml/kg/j de soluté. En majorant l'apport de soluté de 10% sous photothérapie, la quantité de soluté que MM doit recevoir est de :",["A. 234 ml","B. 244 ml","C. 254 ml","D. 264 ml"],[3],"3 × 80 = 240 ml ; majoration de 10 % : 240 + 24 = 264 ml.",null,"29"),
M("PP est né à 39 semaine d'aménorrhée avec une taille de 48 cm, un poids de 3500 grammes et un périmètre crânien de 34 cm. Il est correctement nourri et sa croissance est normale. La taille attendue de PP à l'âge de 4 ans est de :",["A. 100 cm","B. 96 cm","C. 95 cm","D. 90 cm"],[1],"La taille à 4 ans est le double de la taille de naissance : 48 × 2 = 96 cm.",null,"30"),
M("Le périmètre brachial permet d'évaluer l'état nutritionnel de l'enfant entre 0 et 6 mois. Ainsi est considéré comme ayant une malnutrition par carence tout enfant de cette tranche d'âge dont le périmètre brachial est :",["A. En dessous de 11,5 cm","B. Compris entre 11,5 et 12,5 cm","C. Compris entre 12,5 et 13,5 cm","D. Compris entre 13,5 et 14,5 cm"],[0],"Un périmètre brachial inférieur à 11,5 cm traduit une malnutrition aiguë sévère. (À vérifier avec ton corrigé.)",null,"31")
]},
{t:"ABOISSO — Pédiatrie · D.E 2025 (1er sujet, Bloc D) · QCD",d:"Fièvre, gavage, lait de substitution, carnet de santé, F100, croissance, plan de traitement C, prématurité, démarche de soins, otite",qs:[
D("TQ a une fièvre chiffrée à 40°Celsius. Pour normaliser la température de TQ je le déshabille et lui offre à boire.",0,"Vrai. Découvrir l'enfant et le faire boire sont des moyens physiques recommandés.",null,"32"),
D("Nouveau-né de dame KP est hospitalisé au premier jour de vie pour souffrance cérébrale et gavé en discontinu avec du lait maternel. Lorsque la sonde de gavage est en place, je vérifie avant chaque gavage, le résidu gastrique",0,"Vrai. On vérifie le résidu gastrique avant chaque gavage.",null,"33"),
D("Le nourrisson KL est orphelin de mère. A défaut de lait infantile adapter je reconstitue le lait sec entier avec une cuillère à soupe de 10 grammes de lait pour 100ml d'eau bouillie tiédie.",0,"Vrai. (À vérifier avec ton corrigé.)",null,"34"),
D("Dans le nouveau carnet de santé, les directives recommandent de faire une consultation en pédopsychiatrie à partir de l'âge de 4 ans",0,"Vrai d'après la copie photographiée. (À vérifier avec ton corrigé.)",null,"35"),
D("Pour préparer le lait thérapeutique F100, il faut ajouter 2 litres d'eau au contenu du sachet de 456 grammes :",0,"Vrai. Le sachet de F100 de 456 g se dilue dans 2 litres d'eau.",null,"36"),
D("Pendant que le pédiatre effectue la ponction lombaire chez l'enfant, l'infirmière maintient l'enfant pour l'immobiliser. Ce rôle de soins de l'infirmière est un rôle de collaboration",0,"Vrai. Maintenir l'enfant pendant un acte médical est un rôle de collaboration.",null,"37"),
D("Un enfant à croissance normale double son périmètre crânien à quatre ans.",1,"Faux. Le périmètre crânien passe d'environ 35 cm à la naissance à environ 50 cm à 4 ans : il ne double pas.",null,"38"),
D("Au cours de la période de la vie allant de 13 mois à 4 ans, l'enfant qui a une croissance normale gagne au niveau de la taille 2 cm par mois.",1,"Faux. La croissance en taille ralentit : environ 12 cm la deuxième année, puis 6 à 8 cm par an.",null,"39"),
D("Au cours de l'allaitement prépondérant, le nourrisson reçoit le lait maternel, les jus, l'eau et les médicaments",0,"Vrai. Dans l'allaitement prépondérant, le lait maternel est associé à d'autres liquides (jus, eau) et aux médicaments.",null,"40"),
D("Chez un enfant qui fait de la diarrhée, le plan de traitement C est appliqué en cas de signes évidents de déshydratation",1,"Faux. Les signes évidents de déshydratation relèvent du plan B ; le plan C s'applique à la déshydratation sévère.",null,"41"),
D("Un nouveau-né dont l'âge gestationnel est égal à 34 semaines d'aménorrhée est appelé « moyen prématuré » :",0,"Vrai. Moyenne prématurité : 33 à 35 SA.",null,"42"),
D("Le lait de femme est plus riche en protéine que le lait de vache.",1,"Faux. Le lait de vache est plus riche en protéines que le lait de femme.",null,"43"),
D("Pour prévenir une infection de l'œil du nouveau-né après la naissance, je lui administre dans les yeux un antiseptique. La durée de ce traitement est d'un jour",0,"Vrai. Prophylaxie ophtalmique en dose unique à la naissance.",null,"44"),
D("L'enveloppement humide est un moyen physique recommandé dans la prise en charge de la fièvre.",1,"Faux. Il n'est plus recommandé ; on découvre l'enfant, on aère, on fait boire, et on donne du paracétamol.",null,"45"),
D("Les selles de la diarrhée aiguë provoquée par Shiguelle sont pâteuses avec de la glaire et du sang.",0,"Vrai. Les selles de la shigellose sont glairosanglantes.",null,"46"),
D("Lors de la collecte de données d'une démarche de soins infirmiers, je collecte d'abord les signes de la maladie avant le diagnostic médical",0,"Vrai : dans le dossier, le chapitre des signes de la maladie précède le diagnostic médical (même logique que dans le sujet blanc d'Aboisso). (À vérifier avec ton corrigé : la copie photographiée porte « Faux ».)",null,"47"),
D("Dans la démarche de soins infirmiers, les données collectées dans l'identification sont toujours des données d'indépendance",0,"Vrai. Les données d'identification sont des données d'indépendance.",null,"48"),
D("Le streptocoque B est le principal agent infectieux responsable d'infection bactérienne néonatale précoce",0,"Vrai. Le streptocoque B est le principal agent des infections néonatales précoces.",null,"49"),
D("PM souffre d'une otite suppurée. Pour faire les soins des oreilles je nettoie la face interne du pavillon ensuite la face externe",0,"Vrai. (À vérifier avec ton corrigé : la marque de la copie n'est pas lisible.)",null,"50")
]},
{t:"ABOISSO — Pédiatrie · D.E 2025 (1er sujet, Bloc D) · Situation clinique : JG, détresse respiratoire du prématuré",d:"Maladie des membranes hyalines, surfactant, score de Silverman, oxygénothérapie du prématuré",qs:[
M("JG présente probablement",["A. Une inhalation du liquide amniotique","B. Une infection néonatale précoce","C. Une maladie des membranes hyalines","D. Une détresse respiratoire transitoire"],[2],"Prématuré de 32 SA, accouchement sans infection, liquide clair, détresse respiratoire qui s'aggrave progressivement : maladie des membranes hyalines.","<b>SITUATION CLINIQUE</b><br>JG est né à <b>32 semaines d'aménorrhée</b> par voie basse. L'accouchement a été facile sans contexte d'infection maternel. Le liquide amniotique était clair. Après la naissance JG a commencé à présenter une détresse respiratoire s'aggravant progressivement dans le temps.","51.1"),
M("La cause probable de cette détresse respiratoire est :",["A. Une sécrétion insuffisante de surfactant","B. Une malformation cardiaque","C. Une anémie du prématuré","D. Une insuffisance de sécrétion de cortisol"],[0],"La maladie des membranes hyalines est due à un déficit en surfactant, fréquent chez le grand prématuré.",null,"51.2"),
M("L'évaluation de la gravité de la maladie de JG donne : thorax immobile pendant la respiration, tirage intercostal intense et sus sternal, entonnoir xiphoïdien intense, geignement audible à distance, battement des ailes du nez modéré. Le score de Silverman est de",["A. 5","B. 6","C. 7","D. 8"],[3],"Silverman : thorax immobile 1 + tirage intercostal intense 2 + entonnoir xiphoïdien intense 2 + battement des ailes du nez modéré 1 + geignement audible à distance 2 = 8. (À vérifier avec ton corrigé.)",null,"51.3"),
M("Lors de la prise en charge de JG, l'agent de santé a administré sur 10 jours de l'oxygène par voie nasale à la dose de 2 litres/minutes. La séquelle à craindre chez JG après ce traitement est",["A. Une insuffisance respiratoire","B. Une cécité","C. Une cirrhose du foie","D. Une rhinite chronique"],[1],"L'oxygénothérapie prolongée chez le grand prématuré expose à la rétinopathie du prématuré, qui peut conduire à la cécité.",null,"51.4")
]}
);

// ===== ABOISSO · D.E 2025 Chirurgie Version C (photos complètes) =====
CATS[0].s.push(
{t:"ABOISSO — Chirurgie · D.E 2025 (Version C) · QCM",d:"Septicémie, perfusion, hernie, peau, post-opératoire, autoclave, mal de Pott, Baxter, adénome, escarres, transfusion",qs:[
M("Parmi les examens complémentaires suivants, indiquez les deux qui sont effectués en cas de septicémie.",["A. Numération Formule Sanguine","B. Hématocrite","C. Ionogramme sanguin","D. Hémoculture"],[0,3],"Septicémie : l'hémoculture identifie le germe dans le sang et la NFS montre le syndrome infectieux (hyperleucocytose). (À vérifier avec ton corrigé : la copie porte A et B.)",null,"1"),
M("Parmi les propositions suivantes, indiquez celle qui correspond au débit de la perfusion de 5 litres de sérum glucosé isotonique à un malade pendant 24h.",["A. 70 gouttes/mn","B. 80 gouttes/mn","C. 90 gouttes/mn"],[0],"Débit (gouttes/mn) = volume (ml) × 20 / durée (mn) = 5000 × 20 / 1440 ≈ 69,4, soit environ 70 gouttes/mn.",null,"2"),
M("Parmi les propositions suivantes, indiquez celle qui constitue un but du traitement de la hernie.",["A. Traiter le contenu du sac herniaire.","B. Faire une réfection pariétale par raphie.","C. Éviter les récidives."],[2],"Le but du traitement de la hernie est d'éviter les récidives (et l'étranglement). Traiter le contenu du sac et refaire la paroi sont des temps de l'intervention.",null,"3"),
M("Parmi les éléments suivants, indiquez les deux qui sont des annexes de la peau.",["A. Condylome","B. Phlyctène","C. Glande","D. Muscle"],[2,3],"Annexes de la peau : glandes (sudoripares, sébacées), poils (avec leur muscle arrecteur) et ongles. Condylome et phlyctène sont des lésions cutanées. (À vérifier avec ton corrigé : la copie porte A et C.)",null,"4"),
M("Parmi les propositions suivantes indiquez les trois éléments de surveillance de la fonction neurologique d'un malade en post-opératoire immédiat.",["A. Coloration","B. Conscience","C. Faciès","D. Déglutition","E. Pression artérielle","F. Audition"],[1,2,5],"Réponses retenues d'après les marques de la copie : conscience, faciès et audition. Coloration et pression artérielle relèvent de la surveillance cardio-circulatoire. (À vérifier avec ton corrigé.)",null,"5"),
M("Parmi les propositions suivantes, indiquez avec quel élément l'autoclave assure la stérilisation",["A. La chaleur sèche","B. La chaleur humide","C. La radiation"],[1],"L'autoclave stérilise par la chaleur humide (vapeur d'eau sous pression). La chaleur sèche est celle du poupinel.",null,"6"),
M("Parmi les propositions suivantes indiquez le germe qui entraine le mal de pott",["A. Le candida Albicans","B. Le streptocoque","C. Le bacille de koch"],[2],"Le mal de Pott est une tuberculose vertébrale : il est dû au bacille de Koch.",null,"7"),
M("Parmi les hernies suivantes, indiquez les deux qui ne sont pas des hernies de l'aine.",["A. La hernie ventrale latérale","B. La hernie inguinale","C. La hernie crurale","D. La hernie de la ligne blanche"],[0,3],"Les hernies de l'aine sont la hernie inguinale et la hernie crurale. Les hernies ventrale latérale et de la ligne blanche sont des hernies de la paroi abdominale.",null,"8"),
M("Indiquez selon la règle de Baxter, le poids d'un brûlé à 50% de sa surface corporelle qui reçoit 9300 ml de soluté les deux premiers jours.",["A. 15,5 kg","B. 31 kg","C. 46,5 kg"],[1],"Baxter : 1er jour 4 ml × poids × SCB, 2e jour la moitié, soit 6 × poids × SCB sur deux jours. Poids = 9300 / (6 × 50) = 31 kg.",null,"9"),
M("Laquelle des malformations congénitales suivantes est définie comme une déviation des jambes en dehors et des genoux en dedans ?",["A. Genu varus","B. Varus équin","C. Genu valgus"],[2],"Le genu valgus correspond aux genoux en dedans et aux jambes en dehors (jambes en X). Le genu varus est l'inverse (jambes arquées). (La copie porte A : à vérifier avec ton corrigé.)",null,"10"),
M("Parmi les signes suivants, indiquez les deux qui sont des signes spécifiques du mal de Pott",["A. Fièvre vespérale","B. Raideur marquée du rachis","C. Gibbosité","D. Altération de l'état Général"],[1,2],"Signes spécifiques du mal de Pott : raideur rachidienne et gibbosité. Fièvre vespérale et altération de l'état général sont des signes généraux non spécifiques.",null,"11"),
M("Parmi les propositions suivantes indiquez les deux qui sont les signes fonctionnels de l'adénome de la prostate",["A. Impériosité mictionnelle","B. Prolongement de la durée de l'éjaculation","C. Diminution de la force et du calibre du jet","D. Rétention urinaire aiguë"],[0,2],"Signes fonctionnels de l'adénome de la prostate : impériosité mictionnelle, pollakiurie, diminution de la force et du calibre du jet. La rétention urinaire aiguë est une complication.",null,"12"),
M("Parmi les complications suivantes des fractures du fémur, indiquez les deux qui sont immédiates",["A. L'atteinte du nerf sciatique","B. Le choc hypovolémique","C. L'amyotrophie du quadriceps","D. La raideur du genou"],[0,1],"Complications immédiates : choc hypovolémique et lésion du nerf sciatique. Amyotrophie du quadriceps et raideur du genou sont des complications tardives. (À vérifier avec ton corrigé.)",null,"13"),
M("Parmi les propositions suivantes, indiquez celle qui correspond au débit de la transfusion de 450ml de sang à un malade en trois heures.",["A. 90 gouttes/mn","B. 50 gouttes/mn","C. 38 gouttes/mn"],[2],"Transfusion : 15 gouttes = 1 ml. Débit = 450 × 15 / 180 mn = 37,5, soit environ 38 gouttes/mn.",null,"14"),
M("Identifier parmi les sites suivants, les trois qui sont les premiers à être affectés par les escarres quand le malade est en position latérale.",["A. Malléole externe","B. Pénis","C. Menton","D. Épaule","E. Tête du trochanter","F. Le front"],[0,3,4],"En décubitus latéral, les points d'appui sont la malléole externe, l'épaule et le grand trochanter. Pénis, menton et front concernent le décubitus ventral.",null,"15"),
M("Parmi les éléments suivants, lequel constitue la première partie du larynx ?",["A. Le nasopharynx","B. Le laryngopharynx","C. L'oropharynx"],[0],"Les propositions sont les trois étages du pharynx : le nasopharynx est le premier (puis l'oropharynx, puis le laryngopharynx). (L'énoncé du sujet écrit « larynx ».)",null,"16")
]},
{t:"ABOISSO — Chirurgie · D.E 2025 (Version C) · QCD",d:"Épaulette, Wolkmann, adénomectomie, colostomie, occlusions, Glasgow, fractures, abcès chaud, pseudarthrose, volet costal, entorse",qs:[
D("Le signe de l'épaulette est la conséquence de la vacuité de la glène dans la luxation de l'épaule.",0,"Vrai. Le signe de l'épaulette relève de l'inspection dans la luxation de l'épaule.",null,"17"),
D("Le syndrome de Wolkmann siège sur les membres inférieurs.",1,"Faux. Le syndrome de Wolkmann (Volkmann) siège sur le membre supérieur (avant-bras, main).",null,"18"),
D("L'irrigation vésicale bien conduite dans l'adénomectomie prévient les infections et les rétentions urinaires postopératoire.",0,"Vrai. L'irrigation évite la formation de caillots et prévient infections et rétentions.",null,"19"),
D("La colostomie est l'abouchement définitif ou provisoire d'un segment du jéjunum à la peau.",1,"Faux. La colostomie est l'abouchement d'un segment du côlon à la peau (celui du jéjunum s'appelle jéjunostomie).",null,"20"),
D("Les occlusions hautes siègent sur l'œsophage.",1,"Faux. Correction : « le grêle ».",null,"21"),
D("La notion d'intervalle libre est déterminée par la cotation de Glasgow.",1,"Faux. L'intervalle libre est la période sans symptôme entre le traumatisme crânien et l'apparition des signes de l'hématome ; le score de Glasgow évalue la conscience.",null,"22"),
D("Les lésions vasculo-nerveuses sont complications secondaires des fractures du membre inférieur.",1,"Faux. Les lésions vasculo-nerveuses sont des complications immédiates.",null,"23"),
D("Les contusions sont des traumatismes fermés de l'abdomen.",0,"Vrai. Dans une contusion, la paroi reste intacte : c'est un traumatisme fermé.",null,"24"),
D("En cas de plastron appendiculaire, il faut faire un drainage.",1,"Faux. Le plastron appendiculaire est traité médicalement (antibiotiques) puis l'appendicectomie est faite à froid ; le drainage concerne l'abcès appendiculaire. (À vérifier avec ton corrigé : la copie porte « Vrai ».)",null,"25"),
D("La stérilisation des champs opératoires et des blouses opératoires se fait à l'aide des poupinels.",1,"Faux. Les textiles se stérilisent à l'autoclave ; le poupinel (chaleur sèche) sert pour les instruments métalliques et la verrerie.",null,"26"),
D("Les diarthroses sont encore appelées articulations immobiles.",1,"Faux. Les diarthroses sont des articulations mobiles. — Support : L3p5 (Doc TD en Chirurgie)",null,"27"),
D("La fracture de Pouteau Colle est une fracture de la partie distale du radius ou fracture juxta-articulaire.",0,"Vrai. C'est une fracture de l'extrémité inférieure du radius.",null,"28"),
D("L'abcès chaud a pour étiologie le Bacille de KOCH d'origine tuberculeuse.",1,"Faux. L'abcès chaud est dû à des germes pyogènes (surtout le staphylocoque). Le bacille de Koch est en cause dans l'abcès froid.",null,"29"),
D("La plaie est une solution de continuité du tissu osseux.",1,"Faux. La plaie est une solution de continuité de la peau ; la rupture de l'os est une fracture.",null,"30"),
D("Le rétrécissement urétral est la réduction de la lumière de l'uretère.",0,"Vrai d'après la copie photographiée. (L'énoncé écrit « uretère » alors que le rétrécissement urétral concerne l'urètre : à vérifier avec ton corrigé.)",null,"31"),
D("En cas de pseudarthrose, il y a un espace entre les fragments osseux.",0,"Vrai. La pseudarthrose est l'absence de consolidation : les fragments restent mobiles, séparés par un espace.",null,"32"),
D("Le volet costal est caractérisé par un trait de fracture sur une ou plusieurs côtes.",1,"Faux. Le volet costal associe des fractures sur plusieurs côtes consécutives, chacune en deux endroits.",null,"33"),
D("Les occlusions intestinales ont une apparition brutale.",0,"Vrai. L'occlusion intestinale aiguë débute brutalement.",null,"34"),
D("L'embarrure est un enfoncement d'un fragment osseux crânien dans la boite crânienne d'origine traumatique.",0,"Vrai.",null,"35"),
D("L'entorse est un traumatisme fermé d'un ligament articulaire.",0,"Vrai.",null,"36"),
D("La moelle épinière s'arrête au niveau de la vertèbre lombaire L2.",1,"Faux d'après la copie photographiée : la moelle épinière s'arrête au niveau de L1. (À vérifier avec ton corrigé.)",null,"37"),
D("L'invagination intestinale est l'une des causes mécaniques de l'occlusion intestinale.",0,"Vrai. — Support : L2p115 (même énoncé corrigé dans le sujet de Korhogo). (La copie photographiée porte « Faux ».)",null,"38"),
D("La hernie inguinale est un épanchement liquidien dans le scrotum des testicules.",1,"Faux. — Support : L2p96 (c'est l'hydrocèle)",null,"39"),
D("L'adénome de la prostate est une tumeur maligne qui se traduit par une hypertrophie de la glande prostatique.",1,"Faux (tumeur bénigne). — Support : L3p154",null,"40")
]},
{t:"ABOISSO — Chirurgie · D.E 2025 (Version C) · Études de cas N°1 et N°2",d:"M. Ekonga (hémopéritoine, contusion abdominale) et M. Motema (rétention urinaire aiguë)",qs:[
M("Quel tableau d'urgence abdominal que présente Monsieur Ekonga ?",["A. Tableau hémorragique de l'abdomen","B. Tableau d'hémato-péritonite","C. Tableau d'hémopéritoine"],[2],"Douleur abdominale avec défense généralisée, matité déclive des flancs, pâleur et ponction abdominale ramenant du sang : hémopéritoine (sang libre dans le péritoine).","<b>ETUDE DE CAS N°1 :</b><br>Monsieur <b>Ekonga</b>, victime d'un accident de la voie publique se plaint d'une forte douleur abdominale avec une défense généralisée. Il présente une matité déclive des flancs et une pâleur prononcée des téguments et des extrémités. Une ponction abdominale a permis de noter une hémorragie intrapéritonéale.<br><i>Consignes : en vous servant des informations du texte ci-dessus répondez aux questions suivantes.</i>","41"),
M("Parmi les examens suivants, lequel est un examen d'imagerie de première intention permettant de visualiser et quantifier l'hémorragie ?",["A. Echographie abdominale","B. Radiographie de l'abdomen sans préparation","C. Radiographie abdominale"],[0],"L'échographie abdominale (FAST) détecte et quantifie l'épanchement de sang, au lit du patient.",null,"42"),
M("Parmi les actions suivantes indiquez les deux qui sont indiquées pour envisager la réanimation de Monsieur Ekonga",["A. Prendre une voie veineuse sure au cathéter","B. Faire la détersion de l'abdomen","C. Identifier rapidement son groupe sanguin","D. Injecter des produits médicamenteux pour calmer les douleurs"],[0,2],"Hémorragie : on prend une voie veineuse sûre pour perfuser et on identifie rapidement le groupe sanguin en vue d'une transfusion.",null,"43"),
M("Parmi les organes suivants, indiquez les trois susceptibles d'être directement atteints en cas de contusion abdominale.",["A. Le foie","B. Le cœur","C. La rate","D. Le poumon"],[0,2,3],"Réponses retenues d'après les marques de la copie : foie, rate et poumon (base du poumon, proche de la région abdominale haute). (À vérifier avec ton corrigé.)",null,"44"),
M("Parmi les propositions suivantes, indiquez où se localise la rate",["A. La fosse iliaque gauche","B. L'hypochondre droit","C. L'hypochondre gauche"],[2],"La rate se situe dans l'hypochondre gauche. (La copie photographiée porte B, mais la rate est à gauche ; la dernière proposition est en partie masquée par le pied de page. À vérifier avec ton corrigé.)",null,"45"),
M("Parmi les propositions suivantes, indiquez de quoi souffre Monsieur Motema.",["A. Rétention urinaire aiguë","B. Adénome de la prostate","C. Rétention urinaire chronique"],[0],"Incapacité brutale et totale d'uriner chez un homme de 60 ans : rétention urinaire aiguë.","<b>ETUDE DE CAS N°2 :</b><br>Vous recevez pendant votre garde, Monsieur <b>Motema</b>, âgé de 60 ans pour incapacité brutale et totale d'uriner.<br><i>Consignes : en vous servant des informations du texte ci-dessus répondez aux questions suivantes.</i>","46"),
M("Parmi les signes suivants indiquez celui qui permet de confirmer le diagnostic que vous avez posé chez Monsieur Motema.",["A. Incapacité d'uriner","B. Besoin impérieux d'uriner","C. Présence d'un globe vésical"],[2],"Le globe vésical (masse sus-pubienne, mate, douloureuse) confirme la rétention urinaire aiguë.",null,"47"),
M("Parmi les actions suivantes, indiquez celle qui doit permettre de soulager immédiatement Monsieur Motema",["A. Intervention chirurgicale","B. Administration d'un antalgique","C. Pose d'une sonde urinaire"],[2],"Le soulagement immédiat de la rétention urinaire aiguë passe par le drainage de la vessie : pose d'une sonde urinaire (ou cathéter sus-pubien).",null,"48")
]}
);


CATS[0].s.push(
{t:"ABOISSO — Chirurgie · D.E 2025 (Version B) · QCM",d:"Septicémie, perfusion, hernie, peau, post-opératoire, autoclave, mal de Pott, Baxter, adénome, escarres, transfusion",qs:[
M("Parmi les examens complémentaires suivants, indiquez les deux qui sont effectués en cas de septicémie.",["A. Numération Formule Sanguine","B. Hématocrite","C. Ionogramme sanguin","D. Hémoculture"],[0,3],"Septicémie : l'hémoculture identifie le germe dans le sang et la NFS montre le syndrome infectieux (hyperleucocytose).",null,"1"),
M("Parmi les propositions suivantes, indiquez celle qui correspond au débit de la perfusion de 5 litres de sérum glucosé isotonique à un malade pendant 24h.",["A. 70 gouttes/mn","B. 80 gouttes/mn","C. 90 gouttes/mn"],[0],"Débit (gouttes/mn) = volume (ml) × 20 / durée (mn) = 5000 × 20 / 1440 ≈ 69,4, soit environ 70 gouttes/mn.",null,"2"),
M("Parmi les propositions suivantes, indiquez celle qui constitue un but du traitement de la hernie.",["A. Traiter le contenu du sac herniaire.","B. Faire une réfection pariétale par raphie.","C. Éviter les récidives."],[2],"Le but du traitement de la hernie est d'éviter les récidives (et l'étranglement). Traiter le contenu du sac et refaire la paroi sont des temps de l'intervention.",null,"3"),
M("Parmi les éléments suivants, indiquez les deux qui sont des annexes de la peau.",["A. Condylome","B. Phlyctène","C. Glande","D. Muscle"],[2,3],"Annexes de la peau : glandes (sudoripares, sébacées), poils (avec leur muscle arrecteur) et ongles. Condylome et phlyctène sont des lésions cutanées.",null,"4"),
M("Parmi les propositions suivantes indiquez les trois éléments de surveillance de la fonction neurologique d'un malade en post-opératoire immédiat.",["A. Coloration","B. Conscience","C. Faciès","D. Déglutition","E. Pression artérielle","F. Audition"],[1,2,5],"Surveillance neurologique : conscience, faciès (expression, mimique) et audition. Coloration et pression artérielle relèvent de la surveillance cardio-circulatoire.",null,"5"),
M("Parmi les propositions suivantes, indiquez avec quel élément l'autoclave assure la stérilisation",["A. La chaleur sèche","B. La chaleur humide","C. La radiation"],[1],"L'autoclave stérilise par la chaleur humide (vapeur d'eau sous pression). La chaleur sèche est celle du poupinel.",null,"6"),
M("Parmi les propositions suivantes indiquez le germe qui entraine le mal de pott",["A. Le candida Albicans","B. Le streptocoque","C. Le bacille de koch"],[2],"Le mal de Pott est une tuberculose vertébrale : il est dû au bacille de Koch.",null,"7"),
M("Parmi les hernies suivantes, indiquez les deux qui ne sont pas des hernies de l'aine.",["A. La hernie ventrale latérale","B. La hernie inguinale","C. La hernie crurale","D. La hernie de la ligne blanche"],[0,3],"Les hernies de l'aine sont la hernie inguinale et la hernie crurale. Les hernies ventrale latérale et de la ligne blanche sont des hernies de la paroi abdominale.",null,"8"),
M("Indiquez selon la règle de Baxter, le poids d'un brûlé à 50% de sa surface corporelle qui reçoit 9300 ml de soluté les deux premiers jours.",["A. 15,5 kg","B. 31 kg","C. 46,5 kg"],[1],"Baxter : 1er jour 4 ml × poids × SCB, 2e jour la moitié, soit 6 × poids × SCB sur deux jours. Poids = 9300 / (6 × 50) = 31 kg.",null,"9"),
M("Laquelle des malformations congénitales suivantes est définie comme une déviation des jambes en dehors et des genoux en dedans ?",["A. Genu varus","B. Varus équin","C. Genu valgus"],[2],"Le genu valgus correspond aux genoux en dedans et aux jambes en dehors (jambes en X). Le genu varus est l'inverse (jambes arquées).",null,"10"),
M("Parmi les signes suivants, indiquez les deux qui sont des signes spécifiques du mal de Pott",["A. Fièvre vespérale","B. Raideur marquée du rachis","C. Gibbosité","D. Altération de l'état Général"],[1,2],"Signes spécifiques du mal de Pott : raideur rachidienne et gibbosité. Fièvre vespérale et altération de l'état général sont des signes généraux non spécifiques.",null,"11"),
M("Parmi les propositions suivantes indiquez les deux qui sont les signes fonctionnels de l'adénome de la prostate",["A. Impériosité mictionnelle","B. Prolongement de la durée de l'éjaculation","C. Diminution de la force et du calibre du jet","D. Rétention urinaire aiguë"],[0,2],"Signes fonctionnels de l'adénome de la prostate : impériosité mictionnelle, pollakiurie, diminution de la force et du calibre du jet. La rétention urinaire aiguë est une complication.",null,"12"),
M("Parmi les complications suivantes des fractures du fémur, indiquez les deux qui sont immédiates",["A. L'atteinte du nerf sciatique","B. Le choc hypovolémique","C. L'amyotrophie du quadriceps","D. La raideur du genou"],[0,1],"Complications immédiates : choc hypovolémique et lésion du nerf sciatique. Amyotrophie du quadriceps et raideur du genou sont des complications tardives.",null,"13"),
M("Parmi les propositions suivantes, indiquez celle qui correspond au débit de la transfusion de 450ml de sang à un malade en trois heures.",["A. 90 gouttes/mn","B. 50 gouttes/mn","C. 38 gouttes/mn"],[2],"Transfusion : 15 gouttes = 1 ml. Débit = 450 × 15 / 180 mn = 37,5, soit environ 38 gouttes/mn.",null,"14"),
M("Identifier parmi les sites suivants, les trois qui sont les premiers à être affectés par les escarres quand le malade est en position latérale.",["A. Malléole externe","B. Pénis","C. Menton","D. Épaule","E. Tête du trochanter","F. Le front"],[0,3,4],"En décubitus latéral, les points d'appui sont la malléole externe, l'épaule et le grand trochanter. Pénis, menton et front concernent le décubitus ventral.",null,"15"),
M("Parmi les éléments suivants, lequel constitue la première partie du larynx ?",["A. Le nasopharynx","B. Le laryngopharynx","C. L'oropharynx"],[0],"Les propositions sont les trois étages du pharynx : le nasopharynx est le premier (puis l'oropharynx, puis le laryngopharynx). (L'énoncé du sujet écrit « larynx ».)",null,"16")
]},
{t:"ABOISSO — Chirurgie · D.E 2025 (Version B) · QCD",d:"Épaulette, Wolkmann, adénomectomie, colostomie, occlusions, Glasgow, fractures, abcès chaud, pseudarthrose, volet costal, entorse",qs:[
D("Le signe de l'épaulette est la conséquence de la vacuité de la glène dans la luxation de l'épaule.",0,"Vrai. Le signe de l'épaulette relève de l'inspection dans la luxation de l'épaule.",null,"17"),
D("Le syndrome de Wolkmann siège sur les membres inférieurs.",1,"Faux. Le syndrome de Wolkmann (Volkmann) siège sur le membre supérieur (avant-bras, main).",null,"18"),
D("L'irrigation vésicale bien conduite dans l'adénomectomie prévient les infections et les rétentions urinaires postopératoire.",0,"Vrai. L'irrigation évite la formation de caillots et prévient infections et rétentions.",null,"19"),
D("La colostomie est l'abouchement définitif ou provisoire d'un segment du jéjunum à la peau.",1,"Faux. La colostomie est l'abouchement d'un segment du côlon à la peau (celui du jéjunum s'appelle jéjunostomie).",null,"20"),
D("Les occlusions hautes siègent sur l'œsophage.",1,"Faux. Correction : « le grêle ».",null,"21"),
D("La notion d'intervalle libre est déterminée par la cotation de Glasgow.",1,"Faux. L'intervalle libre est la période sans symptôme entre le traumatisme crânien et l'apparition des signes de l'hématome ; le score de Glasgow évalue la conscience.",null,"22"),
D("Les lésions vasculo-nerveuses sont complications secondaires des fractures du membre inférieur.",1,"Faux. Les lésions vasculo-nerveuses sont des complications immédiates.",null,"23"),
D("Les contusions sont des traumatismes fermés de l'abdomen.",0,"Vrai. Dans une contusion, la paroi reste intacte : c'est un traumatisme fermé.",null,"24"),
D("En cas de plastron appendiculaire, il faut faire un drainage.",1,"Faux. Le plastron appendiculaire est traité médicalement (antibiotiques) puis l'appendicectomie est faite à froid ; le drainage concerne l'abcès appendiculaire.",null,"25"),
D("La stérilisation des champs opératoires et des blouses opératoires se fait à l'aide des poupinels.",1,"Faux. Les textiles se stérilisent à l'autoclave ; le poupinel (chaleur sèche) sert pour les instruments métalliques et la verrerie.",null,"26"),
D("Les diarthroses sont encore appelées articulations immobiles.",1,"Faux. Les diarthroses sont des articulations mobiles. — Support : L3p5 (Doc TD en Chirurgie)",null,"27"),
D("La fracture de Pouteau Colle est une fracture de la partie distale du radius ou fracture juxta-articulaire.",0,"Vrai. C'est une fracture de l'extrémité inférieure du radius.",null,"28"),
D("L'abcès chaud a pour étiologie le Bacille de KOCH d'origine tuberculeuse.",1,"Faux. L'abcès chaud est dû à des germes pyogènes (surtout le staphylocoque). Le bacille de Koch est en cause dans l'abcès froid.",null,"29"),
D("La plaie est une solution de continuité du tissu osseux.",1,"Faux. La plaie est une solution de continuité de la peau ; la rupture de l'os est une fracture.",null,"30"),
D("Le rétrécissement urétral est la réduction de la lumière de l'uretère.",1,"Faux. Le rétrécissement urétral est la réduction de la lumière de l'urètre (canal de la miction), et non de l'uretère.",null,"31"),
D("En cas de pseudarthrose, il y a un espace entre les fragments osseux.",0,"Vrai. La pseudarthrose est l'absence de consolidation : les fragments restent mobiles, séparés par un espace.",null,"32"),
D("Le volet costal est caractérisé par un trait de fracture sur une ou plusieurs côtes.",1,"Faux. Le volet costal associe des fractures sur plusieurs côtes consécutives, chacune en deux endroits.",null,"33"),
D("Les occlusions intestinales ont une apparition brutale.",0,"Vrai. L'occlusion intestinale aiguë débute brutalement.",null,"34"),
D("L'embarrure est un enfoncement d'un fragment osseux crânien dans la boite crânienne d'origine traumatique.",0,"Vrai.",null,"35"),
D("L'entorse est un traumatisme fermé d'un ligament articulaire.",0,"Vrai.",null,"36"),
D("La moelle épinière s'arrête au niveau de la vertèbre lombaire L2.",1,"Faux. Chez l'adulte, la moelle épinière s'arrête au niveau de L1 (cône médullaire, L1-L2 selon les auteurs).",null,"37"),
D("L'invagination intestinale est l'une des causes mécaniques de l'occlusion intestinale.",0,"Vrai. — Support : L2p115 (même énoncé corrigé dans le sujet de Korhogo).",null,"38"),
D("La hernie inguinale est un épanchement liquidien dans le scrotum des testicules.",1,"Faux. — Support : L2p96 (c'est l'hydrocèle)",null,"39"),
D("L'adénome de la prostate est une tumeur maligne qui se traduit par une hypertrophie de la glande prostatique.",1,"Faux (tumeur bénigne). — Support : L3p154",null,"40")
]},
{t:"ABOISSO — Chirurgie · D.E 2025 (Version B) · Études de cas N°1 et N°2",d:"M. Ekonga (hémopéritoine, contusion abdominale) et M. Motema (rétention urinaire aiguë)",qs:[
M("Quel tableau d'urgence abdominal que présente Monsieur Ekonga ?",["A. Tableau hémorragique de l'abdomen","B. Tableau d'hémato-péritonite","C. Tableau d'hémopéritoine"],[2],"Douleur abdominale avec défense généralisée, matité déclive des flancs, pâleur et ponction abdominale ramenant du sang : hémopéritoine (sang libre dans le péritoine).","<b>ETUDE DE CAS N°1 :</b><br>Monsieur <b>Ekonga</b>, victime d'un accident de la voie publique se plaint d'une forte douleur abdominale avec une défense généralisée. Il présente une matité déclive des flancs et une pâleur prononcée des téguments et des extrémités. Une ponction abdominale a permis de noter une hémorragie intrapéritonéale.<br><i>Consignes : en vous servant des informations du texte ci-dessus répondez aux questions suivantes.</i>","41"),
M("Parmi les examens suivants, lequel est un examen d'imagerie de première intention permettant de visualiser et quantifier l'hémorragie ?",["A. Echographie abdominale","B. Radiographie de l'abdomen sans préparation","C. Radiographie abdominale"],[0],"L'échographie abdominale (FAST) détecte et quantifie l'épanchement de sang, au lit du patient.",null,"42"),
M("Parmi les actions suivantes indiquez les deux qui sont indiquées pour envisager la réanimation de Monsieur Ekonga",["A. Prendre une voie veineuse sure au cathéter","B. Faire la détersion de l'abdomen","C. Identifier rapidement son groupe sanguin","D. Injecter des produits médicamenteux pour calmer les douleurs"],[0,2],"Hémorragie : on prend une voie veineuse sûre pour perfuser et on identifie rapidement le groupe sanguin en vue d'une transfusion.",null,"43"),
M("Parmi les organes suivants, indiquez les trois susceptibles d'être directement atteints en cas de contusion abdominale.",["A. Le foie","B. Le cœur","C. La rate","D. Le poumon"],[0,2,3],"Réponses : foie, rate et poumon (base du poumon, proche de la région abdominale haute).",null,"44"),
M("Parmi les propositions suivantes, indiquez où se localise la rate",["A. La fosse iliaque gauche","B. L'hypochondre droit","C. L'hypochondre gauche"],[2],"La rate se situe dans l'hypochondre gauche.",null,"45"),
M("Parmi les propositions suivantes, indiquez de quoi souffre Monsieur Motema.",["A. Rétention urinaire aiguë","B. Adénome de la prostate","C. Rétention urinaire chronique"],[0],"Incapacité brutale et totale d'uriner chez un homme de 60 ans : rétention urinaire aiguë.","<b>ETUDE DE CAS N°2 :</b><br>Vous recevez pendant votre garde, Monsieur <b>Motema</b>, âgé de 60 ans pour incapacité brutale et totale d'uriner.<br><i>Consignes : en vous servant des informations du texte ci-dessus répondez aux questions suivantes.</i>","46"),
M("Parmi les signes suivants indiquez celui qui permet de confirmer le diagnostic que vous avez posé chez Monsieur Motema.",["A. Incapacité d'uriner","B. Besoin impérieux d'uriner","C. Présence d'un globe vésical"],[2],"Le globe vésical (masse sus-pubienne, mate, douloureuse) confirme la rétention urinaire aiguë.",null,"47"),
M("Parmi les actions suivantes, indiquez celle qui doit permettre de soulager immédiatement Monsieur Motema",["A. Intervention chirurgicale","B. Administration d'un antalgique","C. Pose d'une sonde urinaire"],[2],"Le soulagement immédiat de la rétention urinaire aiguë passe par le drainage de la vessie : pose d'une sonde urinaire (ou cathéter sus-pubien).",null,"48")
]}
);

// ===== MAN =====
CATS[0].s.push(
{t:"MAN — Chirurgie L3 · Examen blanc (antenne de Man) · QCD",d:"Neurologie, hernie, épaule, Glasgow, appendicite, occlusion, brûlures, ponction sus-pubienne",qs:[
D("La neurologie est la discipline médicale qui prend en charge les maladies du système nerveux",0,"Vrai. — Support : L3p1 (Doc de neurologie)",null,"1"),
D("La hernie peut être congénitale ou acquise",0,"Vrai. — Support : L2p93 (Doc chirurgie)",null,"2"),
D("Le signe de l'épaulette est la conséquence de la vacuité de la glène dans la luxation de l'épaule",0,"Vrai. Le signe de l'épaulette relève de l'inspection dans la luxation de l'épaule.",null,"3"),
D("Le syndrome de Wolkmann siège sur les membres inferieurs",1,"Faux. Le syndrome de Wolkmann (Volkmann) siège sur le membre supérieur (avant-bras, main).",null,"4"),
D("S'agissant de la cotation de Glasgow, la décortication est un élément de la réponse verbale",1,"Faux. La décortication relève de la réponse motrice. — Support : L3p4 (Doc Neurochirurgie)",null,"5"),
D("L'ostéoporose est une cause des fractures pathologiques",0,"Vrai.",null,"6"),
D("Le volet costal est une fracture étagée",0,"Vrai. Le volet costal est une fracture étagée de côtes.",null,"7"),
D("Le signe de Rovsing positif est la mise en évidence du signe pathognomonique de l'appendicite",1,"Faux. Le signe de Rovsing (douleur de la fosse iliaque droite à la palpation de la fosse iliaque gauche) est un signe d'orientation, non pathognomonique.",null,"8"),
D("Le principal organe de la région épigastrique est <u>le foie</u>",1,"Faux. Correction : « l'estomac ».",null,"9"),
D("L'occlusion haute siège sur <u>l'œsophage</u>",1,"Faux. Correction : « le grêle ».",null,"10"),
D("La tuméfaction de l'étranglement herniaire est dure, <u>réductible et impulsive à la toux</u>",1,"Faux. Correction : « Irréductible, non impulsive et non expansive a la toux ». — Support : L2p102 (Doc chirurgie)",null,"11"),
D("DIZO, ayant reçu 7,200 litres le deuxième jour de réanimation hydro électrolytique pour un poids de 80kg, est donc brûlé à 45%",0,"Vrai. SCB = QJ2 / (2 × Pds) = 7200 / (2 × 80) = 45 %.",null,"12"),
D("L'adénome de la prostate est une maladie <u>maligne</u>",1,"Faux. Correction : « bénigne ». — Support : L2p154 (Doc chirurgie)",null,"13"),
D("Le mal de pott est une infection disco-vertébrale due au <u>staphylocoque aureus</u>",1,"Faux. Correction : « bacille de Koch ». — Support : L3p31 (Doc chirurgie)",null,"14"),
D("Le traitement de l'appendicite est uniquement chirurgical",0,"Vrai. — Support : L2p111 (Doc chirurgie)",null,"15"),
D("Le signe capital de la péritonite est la contracture abdominale",0,"Vrai.",null,"16"),
D("Les occlusions fonctionnelles sont le fait du dérèglement du système nerveux intestinal",0,"Vrai. — Support : L2p116 (Doc chirurgie)",null,"17"),
D("La hernie n'existe pas chez la femme",1,"Faux. — Support : L2p97 (Doc chirurgie)",null,"18"),
D("Les brûlures provoquées par contact sont plus graves que celles faites par rayonnement",0,"Vrai. Les brûlures par contact (liquides, solides chauds) sont plus profondes que celles par rayonnement.",null,"19"),
D("La ponction sus-pubienne est conditionnée par l'impossibilité d'une pose de sonde vésicale",0,"Vrai.",null,"20")
]},
{t:"MAN — Chirurgie L3 · Examen blanc (antenne de Man) · QCM",d:"Luxation de l'épaule, Wolkmann, appendicite, fracture, brûlure, gangrène gazeuse, post-opératoire, sciatalgie",qs:[
M("Les signes ci-dessous relèvent de la palpation dans la luxation de l'épaule (2 réponses) L2p19 (Doc chirurgie)",["A. Abduction irréductible","B. Coup de hache extrême","C. Vacuité de l'espace sous acromial","D. Signe de l'épaulette","E. Rotation externe du bras"],[0,2],"Palpation : abduction irréductible et vacuité de l'espace sous-acromial. Le coup de hache extrême, le signe de l'épaulette et la rotation externe du bras relèvent de l'inspection.",null,"21"),
M("Identifiez dans les items ci-dessous les signes du syndrome de Wolkmann ?",["A. Œdème de la jambe","B. Douleur intense","C. Nausées et vomissements","D. Pâleur et froideur des doigts","E. Hyperthermie","F. Engourdissement ou picotement des doigts"],[1,3,5],"Syndrome de Volkmann (ischémie du membre supérieur) : douleur intense, pâleur et froideur des doigts, engourdissement ou picotement des doigts.",null,"22"),
M("Deux items ne font pas partis des étiologies de l'appendicite aigüe parmi ceux qui sont énumérés en dessous. Lesquels ? (2 réponses)",["A. Infections gastro-intestinales","B. Hernie discale","C. Parasitoses intestinales","D. Corps étrangers","E. Fécalome","F. Alimentation pauvre en viande"],[1,5],"La hernie discale (rachis) et l'alimentation pauvre en viande ne sont pas des étiologies de l'appendicite aiguë (une alimentation pauvre en fibres l'est).",null,"23"),
M("La liste ci-dessous est celle des signes fonctionnels de la fracture ; lesquels ? (2 réponses)",["A. Crépitation osseuse","B. Douleur vive","C. Déformation du membre","D. Impotence fonctionnelle","E. Mobilité anormale du membre atteint"],[1,3],"Signes fonctionnels : douleur vive et impotence fonctionnelle. Crépitation, déformation et mobilité anormale sont des signes physiques.",null,"24"),
M("Sur le lieu de l'accident, certains gestes suivants sont proscrits en cas de fracture du fémur ; lesquels ? (2 réponses)",["A. Préparer psychologiquement à l'intervention du blessé","B. Immobiliser dans une gouttière le membre atteint","C. Chercher à réduire une fracture ouverte","D. Laisser le blessé couché par terre","E. Baliser l'emplacement du patient","F. Faire des manœuvres ou de mobilisations intempestives"],[2,5],"Sont proscrits : chercher à réduire une fracture ouverte et faire des manœuvres ou mobilisations intempestives.",null,"25"),
M("Un brûlé à 30% reçoit 9720 ml de soluté en deux (2) jours. Quel est son poids ? (1réponse)",["A. 50 kg","B. 54 kg","C. 55 kg"],[1],"QJ1 + QJ2 = 9720 ; (4 × Pds × SCB) + (2 × Pds × SCB) = 9720 ; (4 × 30 × Pds) + (2 × 30 × Pds) = 9720 ; (120 × Pds) + (60 × Pds) = 9720 ; 180 × Pds = 9720 ; Pds = 9720 / 180 = 54 kg.",null,"26"),
M("S'agissant de la gangrène gazeuse, les assertions ci-dessous sont justes, sauf trois, Lesquelles ? (3 réponses)",["A. Nécrose tissulaire due à l'infection par des bactéries","B. Nécrose tissulaire sans infection bactérienne","C. Tissus gonflés et suintants","D. Forte circulation sanguine au niveau de la partie atteinte","E. Ne se propage pas à d'autres tissus","F. Se propageant a d'autres tissus"],[1,3,4],"La gangrène gazeuse est une nécrose due à une infection bactérienne, avec tissus gonflés et suintants, circulation sanguine diminuée, et elle se propage à d'autres tissus. Les assertions B, D et E sont donc fausses.",null,"27"),
M("Laquelle des malformations congénitales parmi celles énumérées ci-dessus est une déviation des jambes en dehors et des genoux en dedans (jambes en X) (1 réponse) L1p74 (Doc sémio chirurgicale)",["A. Genu valgus","B. Varus équin","C. Genu varus"],[0],"Le genu valgus correspond aux genoux en dedans et aux jambes en dehors (jambes en X).",null,"28"),
M("Parmi les éléments de la surveillance post opératoire ci-dessous, trois (3) relèvent de l'état végétatif du patient. Lesquels ? L3p9 (Doc Neurochirurgie)",["A. Perméabilité des tuyaux","B. Fréquence respiratoire","C. Pression artérielle","D. Profondeur du coma","E. Niveau de conscience","F. Fréquence cardiaque"],[1,2,5],"Fonctions végétatives : fréquence respiratoire, pression artérielle et fréquence cardiaque. Niveau de conscience et profondeur du coma relèvent de l'état de conscience.",null,"29"),
M("Les signes ci-dessous sont des signes méninges après un traumatisme cranioencéphalique, sauf deux. Lesquels ?",["A. Syndrome Wolkmann","B. Raideur de la nuque","C. Céphalées intenses","D. Hémiplégie","E. Vomissements incoercibles"],[0,3],"Le syndrome de Wolkmann et l'hémiplégie ne sont pas des signes méningés (raideur de la nuque, céphalées intenses, vomissements incoercibles).",null,"30"),
M("La liste ci-dessous comprend les moyens du traitement de la sciatalgie sauf un ; lequel ? (1 réponse) L3p29 (Doc Neurochirurgie)",["A. Traitement chirurgical","B. Traitement radiologique","C. Traitement médicamenteux"],[1],"Le traitement de la sciatalgie est médicamenteux, voire chirurgical ; il n'existe pas de « traitement radiologique ».",null,"31"),
M("Les items ci-dessous font partie des étiologies de l'appendicite aigue exceptes deux ; lesquels ? (2 réponses)",["A. Infections gastro-intestinales","B. Alimentation pauvre en viande","C. Parasitoses intestinales","D. Corps étrangers","E. Hernie discale","F. Fécalome"],[1,4],"Ne sont pas des étiologies : l'alimentation pauvre en viande et la hernie discale.",null,"32")
]},
{t:"MAN — Chirurgie L3 · Examen blanc (antenne de Man) · Cas cliniques",d:"Cas clinique N°1 (TOUALI Ibrahim, volet costal, transfusion) et cas clinique N°2 (Mme KONDE Kalidia, appendicite)",qs:[
M("Qu'est que le volet costal ? (1 réponse)",["A. C'est l'existence de 2 traits de fracture sur une même côte qui isole un fragment intermédiaire qui est Indépendant du reste","B. C'est un type particulier de fracture qui siège sur la tête","C. C'est l'existence de fracture avec enfoncement des os du crane"],[0],"Le volet costal est une fracture étagée : deux traits de fracture sur une même côte isolent un fragment indépendant.","<b>CAS CLINIQUE N°1 (De Q33 à Q36)</b><br>Infirmier au service des urgences chirurgicales de l'EPHD de Lakota, vous recevez pendant votre garde, TOUALI Ibrahim cultivateur âgé de 33 ans pesant 70 kg pour AVP. A l'examen clinique du médecin, il ressort un traumatisme thoraco-abdominal sans solution de continuité, une dyspnée respiratoire accompagnée de sueurs froides. Les examens paracliniques d'urgence révèlent une fracture étagée costale gauche au niveau de l'avant dernière paire de côtes sternales, une rupture appendiculaire, un taux d'hémoglobine 4 g/dl et un groupe sanguin B négatif","33"),
M("Qu'est-ce que la respiration paradoxale ? (1 réponse)",["A. L'expiration entraine l'enfoncement du volet costal et gonflement de la cage thoracique et l'inspiration entraine l'expulsion du volet costal et affaissement de la cage thoracique","B. L'inspiration entraine l'enfoncement du volet costal et gonflement de la cage thoracique et l'expiration entraine l'expulsion du volet costal et affaissement de la cage thoracique","C. A l'inspiration le diaphragme se contracte et descend, la cage thoracique s'élève et le thorax se dilate, et à l'expiration le diaphragme se relâche et remonte ; la cage thoracique se rétracte."],[1],"Respiration paradoxale : à l'inspiration le volet s'enfonce alors que la cage thoracique se gonfle ; à l'expiration le volet est expulsé alors que la cage s'affaisse. C décrit la respiration normale.",null,"34"),
M("De quels examens paracliniques demandés en urgence s'agit-il ? (3réponses)",["A. Echographie abdominale","B. Endoscopie bronchique","C. Radiographie du thorax","D. Groupage sanguin","E. Radiographie Blondeau","F. Ionogramme urinaire"],[0,2,3],"Rupture appendiculaire : échographie abdominale ; fracture costale : radiographie du thorax ; transfusion urgente : groupage sanguin.",null,"35"),
M("Quels types de sang peut recevoir M. TOUALI Ibrahim ? (2 réponses)",["A. B positif","B. O positif","C. AB négatif","D. B négatif","E. O négatif"],[3,4],"Receveur de groupe B négatif : il ne peut recevoir que du sang Rhésus négatif, de groupe B ou O, donc B négatif et O négatif.",null,"36"),
M("Quel sera le débit ? (1 réponse)",["A. 30 gouttes/minute","B. 35 gouttes/minute","C. 38 gouttes/minute"],[1],"D = (Q × 15) / T avec T = (3 × 60) + 15 = 195 min ; D = (450 × 15) / 195 = 34,61 gttes/min ≈ 35 gttes/min.","Avant de l'opérer en urgence, le chirurgien prescrit 1 poche de sang iso groupe (450 ml) à passer en trois heures et quart.","37"),
M("La surveillance infirmière per transfusionnelle de TOUALI Ibrahim comprend quels items ? (3 réponses)",["A. Prise de la TA les 15 premières minutes puis toutes les heures","B. Contrôle de la date et de l'intégrité de la poche","C. Mesure régulière de la fréquence respiratoire","D. Etre attentif aux plaintes du patient","E. Vérification de l'identité du patient","F. Installation confortable du patient"],[0,2,3],"En cours de transfusion : surveiller la TA, la fréquence respiratoire et les plaintes du patient. Le contrôle de la poche, la vérification de l'identité et l'installation relèvent de la phase pré-transfusionnelle.",null,"38"),
M("A quelle affection pensez-vous pour Mme KONDE Kalidia ? (1 réponse)",["A. Ulcère gastroduodénal perforé","B. Salpingite","C. Appendicite"],[2],"Douleur péri-ombilicale migrant vers la fosse iliaque droite, fièvre, Blumberg positif : appendicite.","<b>CAS CLINIQUE N°2 (Q37 a Q41)</b><br>Mme KONDE Kalidia 28 ans sans antécédents médicaux consulte aux urgences pour des douleurs abdominales depuis 24 heures. A l'examen, la douleur d'intensité croissante exacerbée par la mobilisation et la toux a débuté dans la région péri-ombilicale et a migré vers la fosse iliaque droite.<br>On note :<br>➢ T°=38,1°C<br>➢ Signe de Blumberg positif<br>➢ Pas de défense ni de contracture abdominale<br>➢ Test de grossesse négatif","39"),
M("Quels sont les diagnostics chirurgicaux différentiels à évoquer chez Mme KONDE Kalidia ? (2 réponses)",["A. Grossesse tubaire rompue","B. Colique néphrétique droite","C. Torsion de kyste","D. Ovarite droite","E. Appendicite rompue","F. Salpingite droite"],[0,2],"Diagnostics chirurgicaux différentiels retenus : grossesse tubaire rompue et torsion de kyste.",null,"40"),
M("Quels sont les éléments de la prise en charge de Mme KONDE Kalidia ? (2réponses)",["A. Lancer le bilan préopératoire","B. Prise de voie veineuse","C. Mise en quarantaine","D. Administration d'antalgiques","E. Demander les examens de confirmation du diagnostic"],[0,1],"Prise en charge d'une appendicite à opérer : bilan préopératoire et pose d'une voie veineuse.",null,"41"),
M("Pourquoi l'échographie est-elle privilégiée chez Mme KONDE Kalidia ? (2 réponses)",["A. Elle est inappropriée que la tomodensitométrie","B. Elle est économique et permet de rassurer le patient","C. Elle est moins chère et permet de visualiser un appendice inflammatoire","D. Elle est moins invasive et plus accessible que le scanner","E. Elle est inaccessible et couteuse"],[1,2],"L'échographie est économique et permet de visualiser un appendice inflammatoire.",null,"42"),
M("Quels sont les risques que court Mme KONDE Kalidia si sa prise en charge est tardive ? (3 réponses)",["A. Perforation de l'appendice","B. Formation d'un abcès appendiculaire","C. Impuissance sexuelle","D. Cardiomégalie","E. Stérilité","F. Sepsis en cas d'infection non contrôlée"],[0,1,5],"Une appendicite prise en charge tardivement expose à la perforation, à l'abcès appendiculaire et au sepsis.",null,"43")
]}
);
CATS[1].s.push(
{t:"MAN — Médecine L3 · Cas clinique M. KPAN (Version C)",d:"Hypertension artérielle : diagnostic, facteur de risque, complication, conduite à tenir",qs:[
M("Quelle est votre hypothèse diagnostique ? L2p4(Doc de médecine)",["A. Insuffisance cardiaque","B. Hypertension artérielle","C. Infection urinaire","D. Diabète insipide"],[1],"Céphalées occipitales matinales, acouphènes, mouches volantes et pollakiurie nocturne orientent vers l'hypertension artérielle.","<b>PARTIE III : CAS CLINIQUE</b><br>Vous êtes de garde au service des urgences médicales du CHR de Duékoué. Vous recevez M. KPAN âgé de 53 ans. Il est instituteur. Il est hospitalisé. A l'interrogatoire il se plaint de : <u>céphalées occipitales matinales</u>, <u>acouphènes</u>, <u>sensations de mouches volantes</u>, <u>pollakiurie nocturne</u>.","1"),
M("Donner un facteur de risque de cette maladie",["A. Polyurie","B. Insalubrité","C. Diabète"],[2],"Le diabète est un facteur de risque de l'hypertension artérielle.",null,"2"),
M("Citer une manifestation des complications de cette pathologie",["A. Épistaxis","B. Céphalée","C. Hyperthermie","D. Polydipsie"],[0],"L'épistaxis peut traduire une complication de l'hypertension artérielle.",null,"3"),
M("Quelle est votre conduite à tenir en tant qu'infirmier ? (Deux réponses)",["A. Mesurer la température","B. Mesurer la pression artérielle aux deux bras","C. Créer un environnement calme","D. Administrer un antalgique","E. Donner à boire au malade"],[1,2],"Mesurer la pression artérielle aux deux bras et créer un environnement calme.",null,"4"),
D("L'un des rôles propres de l'infirmier dans cette prise en charge consiste à faire une bandelette urinaire a la recherche de protéinurie et d'hématurie.",0,"Vrai.",null,"5"),
D("Le besoin de s'occuper en vue de se réaliser n'est pas satisfait chez monsieur KPAN.",0,"Vrai.",null,"6")
]},
{t:"MAN — Médecine L3 · Épreuve de soins infirmiers (Version C) · QCD",d:"TDR, diabète, VIH, IMC, fièvre typhoïde, pneumonie, paludisme, covid 19, dengue, AVC",qs:[
D("Le TDR est un examen de <u>référence</u> pour établir le diagnostic de paludisme.",1,"Faux. Correction : « certitude ».",null,"7"),
D("Le diabète de type 2 résulte d'une mauvaise utilisation de l'insuline par l'organisme.",0,"Vrai.",null,"8"),
D("Le diabète de type 2 est aussi appelé diabète de la maturité.",0,"Vrai.",null,"9"),
D("L'hyperglycémie est une élévation de la teneur en sucre dans le sang.",0,"Vrai.",null,"10"),
D("Le diabète a des conséquences sur le cœur, les yeux, les reins et les nerfs et les vaisseaux sanguins.",0,"Vrai.",null,"11"),
D("Chez l'adulte le premier test rapide utilisé pour le dépistage du VIH est le détermine.",0,"Vrai.",null,"12"),
D("L'indice de masse corporel (IMC)d'une personne de poids 79 kg et de taille 1m 80 est de IMC=24,38",0,"Vrai. IMC = 79 / (1,80)² = 79 / 3,24 = 24,38.",null,"13"),
D("La charge virale est la quantité de virus présente dans le sang.",0,"Vrai.",null,"14"),
D("L'utilisation de préservatifs <u>n'est pas nécessaire</u> si le patient prend des ARV",1,"Faux. Correction : « nécessaire ».",null,"15"),
D("La prévention de la transmission du VIH inclut uniquement la prise d'ARV après l'accouchement.",1,"Faux.",null,"16"),
D("Avant de mesurer la pression artérielle d'un malade il doit être au repos <u>pendant 5 minutes</u>.",1,"Faux. Correction : « pdt au moins 5min ».",null,"17"),
D("Les cardiopathies coronariennes touchent les vaisseaux sanguins qui alimentent le muscle cardiaque <u>et le cerveau</u>.",1,"Faux. Correction : « cerveau → AVC ».",null,"18"),
D("L'asthme est une inflammation des voies respiratoires entrainant une hyperactivité des bronches.",0,"Vrai.",null,"19"),
D("Les bactéries sont responsables des maladies infectieuses <u>et parasitaires</u>.",1,"Faux. Correction : « bactériennes ».",null,"20"),
D("Le réservoir de germe dans la fièvre typhoïde est strictement <u>animal</u>.",1,"Faux. Correction : « humain ».",null,"21"),
D("Dans la fièvre typhoïde, il existe deux modes de contamination.",0,"Vrai. « Directe et Indirecte ».",null,"22"),
D("Une pneumonie lobaire est une infection de <u>toutes les portions du poumon</u>.",1,"Faux. Correction : « un seul lobe pulmonaire ».",null,"23"),
D("La cyanose est un signe de gravite en cas de détresse respiratoire.",0,"Vrai.",null,"24"),
D("La réduction du nombre de maladies opportunistes, d'hospitalisations, de décès liés au VIH et l'amélioration de l'espérance de vie fait partie des principes de base du TARV.",0,"Vrai.",null,"25"),
D("La goutte épaisse et le Frottis sanguin permettent de <u>déterminer l'espèce plasmodiale et la densité parasitaire</u>.",0,"Vrai.",null,"26"),
D("Le TDR ne permet pas d'évaluer l'efficacité du paludisme.",0,"Vrai.",null,"27"),
D("La quinine par voie orale est un traitement de 2eme intention du paludisme.",0,"Vrai.",null,"28"),
D("La transmission de la covid 19 est <u>strictement directe</u>.",1,"Faux. Correction : « directe et indirecte ».",null,"29"),
D("L'agent pathogène de la dengue est un arbovirus du genre Aèdes.",0,"Vrai.",null,"30"),
D("L'homme est l'unique réservoir de virus de la dengue.",0,"Vrai.",null,"31"),
D("Le diabète multiplie le risque de souffrir d'AVC.",0,"Vrai.",null,"32")
]},
{t:"MAN — Médecine L3 · Épreuve de soins infirmiers (Version C) · QCM",d:"TDR, débit de perfusion, paludisme, bilharziose, ascaris, diabète, méningite, dengue, ARV, diurétiques",qs:[
M("Le milieu de Conservation du Kit complet du TDR doit être de :",["A. 2 et 40 °C","B. 4 et 40 °C","C. 4 et 20 °C"],[1],"Le kit complet du TDR se conserve entre 4 et 40 °C.",null,"33"),
M("Quel est le débit d'une perfusion de sérum glucosé isotonique de 500 ml avec 8 cc sels de quinine et 8 cc d'électrolyte ? Durée 4 heures.",["A. 40 gouttes/minute","B. 41 gouttes/minute","C. 42 gouttes/minute","D. 43 gouttes/minutes"],[3],"Q = 500 + 8 + 8 = 516 ml. D = (Q × 20) / (T × 60) = (516 × 20) / (4 × 60) = 43 gouttes/minute.",null,"34"),
M("Si, après le traitement antipaludique, le patient revient pour un nouvel épisode de fièvre plus de deux semaines",["A. Il doit faire un nouveau TDR","B. Il doit faire un nouveau traitement antipaludique","C. Il doit être teste par l'examen de GE ou FS."],[2],"Au-delà de deux semaines, le TDR peut rester positif : le patient doit être testé par la goutte épaisse (GE) ou le frottis sanguin (FS).",null,"35"),
M("Pour un patient vu au niveau périphérique, présentant des symptômes graves de paludisme, il faudra",["A. Commencer immédiatement le traitement antipaludique par voix veineuse","B. Effectuer immédiatement un TDR et le mettre en observation pendant trois jours","C. Effectuer immédiatement un TDR et référer le patient avec un traitement de pré-transfert."],[2],"Au niveau périphérique : TDR immédiat puis référence avec un traitement de pré-transfert.",null,"36"),
M("Parmi les propositions suivantes, indiquez la bonne réponse. Dans la Bilharziose à Schistosoma Haematobium, l'hématurie est : L1p18(Doc maladie infectieuse)",["A. Capricieuse, non douloureuse, intermittente, récidivante","B. Capricieuse, douloureuse, intermittente, récidivante","C. Capricieuse, douloureuse, intermittente, non récidivante"],[1],"L'hématurie de la bilharziose urinaire est capricieuse, douloureuse, intermittente et récidivante.",null,"37"),
M("Parmi les propositions suivantes, indiquez la bonne réponse. La Bilharziose peut avoir des complications. L1p19(Doc maladie infectieuse)",["A. Vésicales, Urétrales, Rénales, Génitales","B. Vésicales, Urétrales, Pulmonaires, Génitales","C. Vésicales, Urétrales, Cardiaques, Génitales"],[0],"Complications : vésicales, urétrales, rénales et génitales.",null,"38"),
M("La présence d'Ascaris adultes dans la voie biliaire et pancréatique entraine les signes suivants sauf un lequel ? L1p22(Doc maladie infectieuse)",["A. Colique hépatique","B. Appendicite aigue","C. Angiocholite aigue"],[1],"L'appendicite aiguë n'est pas due à la présence d'Ascaris dans les voies biliaire et pancréatique.",null,"39"),
M("Parmi les propositions suivantes, indiquez la bonne réponse. Les déterminants de la transmission de l'Ascaris sont : L1p21(Doc maladie infectieuse)",["A. La sècheresse, l'humidité, le péril fécal","B. La chaleur, l'humidité, le péril fécal","C. La chaleur, le froid, le péril fécal"],[1],"Déterminants : chaleur, humidité et péril fécal.",null,"40"),
M("Parmi les propositions suivantes, indiquez la bonne réponse. L'ankylostomose se transmet par voie : L1p20(Doc maladie infectieuse)",["A. Cutanée et orale","B. Exclusivement cutanée","C. Exclusivement orale"],[1],"L'ankylostomose se transmet exclusivement par voie cutanée (pénétration des larves à travers la peau).",null,"41"),
M("Les mesures suivantes permettent de prévenir la teniase sauf un. Lequel ? L1p38(Doc maladie infectieuse)",["A. Cuisson suffisante de la viande de bœuf.","B. Abattage de tous les porteurs de ténia,","C. Construction et utilisation des latrines,"],[1],"L'abattage de tous les porteurs de ténia n'est pas une mesure de prévention de la téniase.",null,"42"),
M("Parmi les propositions suivantes, indiquez les bonnes réponses. Les symptômes du diabète de type 1 sont:(03 réponses)",["A. Polyurie","B. Dysphagie","C. Faim constante","D. Prise de poids","E. Polydipsie","F. Pollakiurie"],[0,2,4],"Diabète de type 1 : polyurie, polydipsie et faim constante (polyphagie), avec amaigrissement (non prise de poids).",null,"43"),
M("Parmi les examens de laboratoires suivant, deux ne sont pas indiqués dans le diagnostic du diabète. Lesquels ?",["A. La coproculture","B. La glycémie","C. NFS","D. Acétonurie","E. La glycosurie"],[0,2],"La coproculture et la NFS ne sont pas indiquées dans le diagnostic du diabète (glycémie, glycosurie, acétonurie le sont).",null,"44"),
M("L'insuline est une hormone secrétée par :",["A. Le foie","B. Le pancréas exocrine","C. Le pancréas endocrine"],[2],"L'insuline est sécrétée par le pancréas endocrine (îlots de Langerhans).",null,"45"),
M("Quels sont les deux signes du syndrome infectieux de la méningite purulente parmi les propositions suivantes ? L1p101(Doc maladie infectieuse)",["A. Fièvre à 39-40°C","B. Raideur de la nuque","C. Convulsions","D. Signes de Kerning positifs","E. Pouls rapide"],[0,4],"Syndrome infectieux : fièvre à 39-40 °C et pouls rapide. Raideur de la nuque et signes de Kernig relèvent du syndrome méningé.",null,"46"),
M("Parmi les propositions suivantes identifiez celles qui sont conformes aux différentes formes de la dengue ? (02 réponses)",["A. Dengue fébrile","B. Dengue frusque","C. Dengue sévère","D. Dengue fébrile hémorragique"],[0,3],"Formes : dengue fébrile (classique) et dengue fébrile hémorragique.",null,"47"),
M("Parmi les propositions suivantes, laquelle est vraie ? Les souches du virus de la dengue se répartissent :",["A. En trois sérotypes distincts","B. En quatre sérotypes distincts","C. En cinq sérotypes distincts"],[1],"4 sérotypes distincts : DENV-1, DENV-2, DENV-3, DENV-4.",null,"48"),
M("Comment préparer le patient au traitement ARV ? (03 réponses)",["A. Faire comprendre au patient l'importance d'une bonne observance ;","B. Gérer les effets indésirables des ARV","C. Faire savoir au patient que le traitement ARV est un traitement de longue durée ou à vie.","D. Choisir le bon schéma de traitement ;","E. Respecter le calendrier de suivi ;","F. Prendre en compte les préoccupations et les priorités du patient ;"],[0,2,5],"Préparation du patient : bonne observance, traitement de longue durée ou à vie, prise en compte de ses préoccupations et priorités.",null,"49"),
M("Quelle est la contre-indication des diurétiques parmi les propositions suivantes ?",["A. Insuffisance cardiaque","B. Syndrome néphrotique","C. Trouble potassique","D. Insuffisance hépatique"],[2],"Les troubles potassiques (hypokaliémie, hyperkaliémie selon le diurétique) contre-indiquent les diurétiques.",null,"50")
]}
);
CATS[3].s.push(
{t:"MAN — Santé publique · Examen blanc N°1 INFAS MAN (Version C) · Étude de cas N°1 : budgétisation",d:"Budgétisation des ressources propres du CSR de GBANGBEUGOUINE (Q1 à Q6)",qs:[
M("Quel est le montant de la somme a la banque après mouvement bancaire ?",["A. 8666500 f","B. 8665005 f","C. 8566650 f","D. 8065566 f"],[0],"SB après mouvement bancaire = 8645000 + 65000 − 43500 = 8666500.","<b>A/ ETUDE DE CAS N°1 (Budgétisation des ressources propres)</b><br>La somme a la banque a la veille du monitorage du Centre de santé Rural de GBANGBEUGOUINE est de 8645000 f pour l'exercice 2024 non compris les intérêts et y compris les agios qui représentent respectivement 65000f et 43500f.Il faut noter que le montant pendant les six mois couverts par le monitorage a été déposée à la banque. Les recettes du centre issues de la vente des médicaments essentiels représentent le quart de la somme a la banque. Celles issues des coûts des actes sont égales à la moitié de la somme a la banque après mouvement bancaire. Les dépenses obligatoires du centre de santé font 4050000 f.<br>A partir des données financières du centre de santé rural pour l'année 2024","Q1"),
M("Quel est la somme issue de la vente des médicaments essentiels ?",["A. 8666500 f","B. 8665005 f","C. 2161250 f","D. 8065566 f"],[2],"RVME représentent le quart de la somme à la banque (SB), avec SB = 8645000 : RVME = SB / 4 = 8645000 / 4 = 2161250.",null,"Q2"),
M("Quel est la somme issue des recettes des actes de santé ?",["A. 4053253 f","B. 4350235 f","C. 4332350 f","D. 4333250 f"],[3],"RCAS sont égales à la moitié de la somme à la banque après mouvement bancaire : RCAS = 8666500 / 2 = 4333250.",null,"Q3"),
M("Quel est la valeur de la somme à budgétiser ?",["A. 6945400 f","B. 6500495 f","C. 6494500 f","D. 6944005 f"],[2],"SAB = RVME + RCAS = 2161250 + 4333250 = 6494500.",null,"Q4"),
M("Quel est la valeur des dépenses de fonctionnement local ?",["A. 2445400 f","B. 2444500 f","C. 2500445 f","D. 2440005 f"],[1],"SAB = DO + DFL, donc DFL = SAB − DO = 6494500 − 4050000 = 2444500.",null,"Q5"),
M("Quel est la valeur des autres dépenses de fonctionnement local en dehors des montants réservés à l'immeuble et aux imprévus ?",["A. 2877025 f","B. 2770285 f","C. 2077825 f","D. 22580770 f"],[2],"AUTRES = 85 % × DFL = 85 % × 2444500 = 2077825.",null,"Q6")
]},
{t:"MAN — Santé publique · Examen blanc N°1 INFAS MAN (Version C) · Étude de cas N°2 : monitorage",d:"Monitorage de la vaccination des jeunes filles de 9 ans (Q7 à Q12 et Q14)",qs:[
M("Quelle est la population cible annuelle ?",["A. 279 jeunes filles de 9 ans","B. 297 jeunes filles de 9 ans","C. 227 jeunes filles de 9 ans","D. 272 jeunes filles de 9 ans"],[0],"Pop jeunes filles = 1,86 % × Pt = 1,86 % × 15000 = 279.","<b>B/ ETUDE CAS N°2 (Monitorage des activités)</b><br>Un monitorage portant sur l'activité de vaccination des jeunes filles de 9 ans du centre de santé rurale de GBANGBEUGOUINE pour la période du 01/06/2020 au 31/12/2020 a donné les résultats ci- dessous. Rappelons que la population totale du bassin de desserte était 15000 habitants au 31/12/2020<br>Disponibilité des ressources : 65%<br>Accessibilité géographique : 70%<br>Utilisation des services : 80%<br>Couverture adéquate : 50%<br>Couverture effective : 30%<br>A partir de la population totale du centre de santé rural","Q7"),
M("Quelle est la population cible du monitorage ?",["A. 103 jeunes filles de 9 ans","B. 104 jeunes filles de 9 ans","C. 140 jeunes filles de 9 ans","D. 107 jeunes filles de 9 ans"],[2],"Pop jeunes filles du monitorage = 279 / 2 = 140 (le monitorage couvre six mois).",null,"Q8"),
M("Quelle est la durée du monitorage ?",["A. 181 jours","B. 187 jours","C. 182 jours","D. 183 jours"],[3],"Pour la période du 01/06/2020 au 31/12/2020, la durée du monitorage est de 183 jours.",null,"Q9"),
M("Combien de goulots d'étranglement a ressorti le monitorage (01 seule réponses) ?",["A. 05 goulots d'étranglement","B. 03 goulots d'étranglement","C. 01 goulots d'étranglement","D. 02 goulots d'étranglement"],[1],"PC − DR − AG − US − CA − CE : 100 % − 65 % − 70 % − 80 % − 50 % − 30 %. Les écarts entre indicateurs successifs sont 35 %, −5 %, −10 %, 30 % et 20 % : trois goulots ressortent (35 %, 30 % et 20 %).",null,"Q10"),
M("Quels sont les sites des trois goulots d'étranglement ressortis par le monitorage ?",["A. 01 goulots d'étranglement entre la population cible et la disponibilité des ressources","B. 01 goulots d'étranglement entre la disponibilité des ressources et Inaccessibilité géographique","C. 01 goulots d'étranglement entre l'accessibilité géographique et l'utilisation des services","D. 01 goulots d'étranglement entre l'utilisation des services et la couverture adéquate","E. 01 goulots d'étranglement entre la couverture adéquate et la couverture effective"],[0,3,4],"Les trois plus grands écarts : population cible → disponibilité des ressources (35 %), utilisation des services → couverture adéquate (30 %), couverture adéquate → couverture effective (20 %).",null,"Q11"),
M("Quels sont les causes correspondantes aux trois goulots d'étranglement ressortis par le monitorage ?",["A. La population de jeunes filles n'a pas bénéficié des vaccins de qualité","B. Le centre de santé n'est pas fréquenté par jeunes filles de 9 ans","C. Les jeunes filles de 9 ans sont très éloignées du centre de santé","D. L'infirmier de la localité ne respecte l'intervalle de commande de vaccin recommande dans les centres de santé périphériques","E. Le centre de santé n'est pas intensément fréquenté par les jeunes filles de 9 ans","F. Existence de préjugés sur la vaccination au sein de la population"],[0,3,4],"Un goulot, une cause : population cible → disponibilité des ressources (35 %) : l'infirmier ne respecte pas l'intervalle de commande de vaccin (D) ; utilisation des services → couverture adéquate (30 %) : le centre de santé n'est pas intensément fréquenté par les jeunes filles (E) ; couverture adéquate → couverture effective (20 %) : les jeunes filles n'ont pas bénéficié de vaccins de qualité (A).",null,"Q12"),
M("Quels sont les trois supports de données qui ont permis de faire le monitorage. L3P11",["A. La fiche de stock du vaccin HPV","B. Le livret de bord de la moto de l'infirmier","C. Le registre de vaccination","D. La fiche de relevé de la température du réfrigérateur du centre de sante","E. Le registre de consultation","F. La fiche d'entretien du réfrigérateur du centre de santé"],[0,2,3],"Supports de données du monitorage de la vaccination : fiche de stock du vaccin, registre de vaccination et fiche de relevé de la température du réfrigérateur.",null,"Q14")
]},
{t:"MAN — Santé publique · Examen blanc N°1 INFAS MAN (Version C) · QCD",d:"Santé communautaire, vaccination, monitorage, budgétisation, SSP (Q15 à Q39)",qs:[
D("La santé communautaire vise la protection de la population.",1,"Faux. — Support : L1p8",null,"Q15"),
D("La santé publique se situe au niveau de la communauté.",1,"Faux. — Support : L1p8",null,"Q16"),
D("Le niveau décisionnel de la sante publique se situe au niveau étatique.",0,"Vrai. — Support : L1p8",null,"Q17"),
D("Le système de santé ivoirien est sous forme pyramidale avec deux versants et trois niveaux.",0,"Vrai. — Support : L1p35",null,"Q18"),
D("Un enfant qui suit correctement son calendrier de vaccination, reçoit le VPO1 a 10 semaines.",1,"Faux. — Support : L1p46",null,"Q19"),
D("Un enfant séropositif qui suit correctement son calendrier de vaccination, reçoit le RR-1 à 6 mois.",1,"Faux. — Support : L1p46",null,"Q20"),
D("A la 14eme semaine de vie, le nourrisson doit recevoir idéalement les doses de vaccin comme suit : DTCHepBHib+VPO+Pev13 +Rota et VPI.",1,"Faux. — Support : L1p46",null,"Q21"),
D("Dans le monitorage de l'activité de vaccination, la mauvaise estimation des besoins en vaccins est une cause probable du goulot d'étranglement situe entre la population cible et l'accessibilité géographique aux soins.",1,"Faux. — Support : L2p81",null,"Q22"),
D("Dans le monitorage des activités, les déterminants de couverture mesurent les indicateurs.",0,"Vrai. — Support : L3p4",null,"Q23"),
D("L'accessibilité géographique aux soins dans le monitorage des consultations des soins curatifs se définit comme la population cible habitant dans un rayon de moins de 10 km.",0,"Vrai. — Support : L3p5",null,"Q24"),
D("L'accueil humaniste des populations par les agents de santé est la stratégie pour corriger le goulot d'étranglement entre la couverture adéquate et l'utilisation de service.",0,"Vrai. — Support : L2p80",null,"Q25"),
D("Il n'y a pas de différence entre les ressources propres et les ressources brutes d'une structure de Santé.",1,"Faux. — Support : L3p13",null,"Q26"),
D("La somme à budgétiser est aussi appelée le fonds de réserve dans la budgétisation des ressources Propres d'un ESPC dans le cadre des SSP.",0,"Vrai. — Support : L3p15",null,"Q27"),
D("La somme à budgétiser est égale aux recettes issues de la vente des médicaments essentiels plus celles issues du cout des actes de santé.",0,"Vrai. — Support : L3p16",null,"Q28"),
D("La somme allouée aux imprévus dans la budgétisation des ressources propres d'un centre de santé rural ne doit pas excéder 10%des recettes brutes.",1,"Faux. — Support : L3p16",null,"Q29"),
D("les étapes de l'organisation d'une séance de vaccination commencent toujours l'enregistrement de la population cible à vacciner.",1,"Faux. — Support : L3p61",null,"Q30"),
D("Un enfant âgé de 2 semaines ayant déjà reçu le VPO0, le BCG et sa dose d'hépatite B a la naissance est correctement vaccine.",0,"Vrai. — Support : L2p38",null,"Q31"),
D("Un enfant correctement vacciné est celui qui reçoit toutes les doses de vaccins inscrites dans le programme élargi de vaccination.",1,"Faux. — Support : L2p38",null,"Q32"),
D("Un enfant de 8 mois ayant reçu toutes ses doses de vaccins à l'exception des doses de RR1 et du VAA et du Men A est correctement vacciné",0,"Vrai. Le RR1 est à 9 mois.",null,"Q33"),
D("Un vaccin dont la PCV à virée et qui ne peut plus être utilise est un vaccin sacrifié.",1,"Faux. — Support : L2p38",null,"Q34"),
D("Au cours de la gestion des vaccins, la règle PEPU permet d'éviter les doses gaspillées.",1,"Faux. — Support : L2p47",null,"Q35"),
D("Le niveau de mise en œuvre des soins de santé primaires est aussi appelé niveau primaire.",0,"Vrai. — Support : L1p75",null,"Q36"),
D("Le niveau de mise en œuvre des soins de santé primaires est aussi appelé périphérique.",0,"Vrai. — Support : L1p75",null,"Q37"),
D("La conférence du 6 au 12 septembres 1978 au cours de laquelle la politique des SSP a été définie par l'OMS a eu lieu à ATA-ALMA en ex URSS.",1,"Faux. — Support : L1p74",null,"Q38"),
D("L'Hôpital général est l'une des structures prestataires du niveau périphérique de la pyramide Sanitaire ivoirienne.",1,"Faux.",null,"Q39")
]},
{t:"MAN — Santé publique · Examen blanc N°1 INFAS MAN (Version C) · Étude de cas N°3 : épidémiologie",d:"Accroissement de la population, accouchement assisté, incidence, mortalité infantile et maternelle (Q40 à Q47)",qs:[
M("Quel est le taux d'accroissement annuel de la population du CSR de GBANGBEUGOUINE en 2024 ?",["A. 3,75%","B. 3,57%","C. 3,35%","D. 3,53%"],[1],"TAA = ((Pf − Pd) / Pd) × 100 = ((14500 − 14000) / 14000) × 100 = 3,57 %.","<b>D/ ETUDE DE CAS N°3(Epidémiologie)</b><br>La population au 31/12/2020 du bassin de desserte du centre rurale de GBANGBEUGOUINE, dans le district sanitaire de MAN est estimée à 14500habitants contre 14000 habitants au 01/01/2020. Les données démographiques et sanitaires ci-dessous ont été enregistrées au cours de l'année 2024<br>Naissances vivantes : 120<br>Nombre d'accouchement effectue par la sage-femme et les accoucheuses traditionnelles du bassin de desserte : 80<br>Décès toutes causes confondues : 55<br>Effectifs d'accouchement attendus : 705<br>250 cas de paludisme parmi lesquels : 10 cas décès ont été dénombrés<br>320 cas de maladies diarrhéiques sont les 2/3 sont des anciens cas<br>8 décès de femmes enceintes dont 2 survenus des suites d'un accident survenu du retour des champs<br>03 enfants dont l'âge est compris entre 0 et 11 mois sont morts dès suite d'une malnutrition sévère<br><b>QUESTIONS :</b> A partir des données démographiques et sanitaires du centre de santé rural de GBANGBEUGOUINE:","Q40"),
M("Quel est la population du CSR de GBANGBEUGOUINE au 01/01/2024 ?",["A. 16566 Habitants","B. 16665 Habitants","C. 16516 Habitants","D. 16615 Habitants"],[2],"P(01/01/2024) = P(01/01/2020) × (1 + TAA/100)^4 = 14000 × (1 + 3,57/100)^4 = 16109 habitants. Aucune proposition ne correspond exactement au calcul : la proposition la plus proche du résultat est retenue.",null,"Q41"),
M("Quel est la population du CSR de GBANGBEUGOUTNE au 31/12/2024 ?",["A. 17062 Habitants","B. 17620 Habitants","C. 17026 Habitants","D. 17260 Habitants"],[2],"P(31/12/2024) = P(31/12/2023) × (1 + TAA/100)^1 = 16109 × (1 + 3,57/100) = 16685 habitants. Aucune proposition ne correspond exactement au calcul : la proposition la plus proche du résultat est retenue.",null,"Q42"),
M("Quel est la population moyenne du CSR de GIBANGBEUGOUINE en 2024 ?",["A. 16693 Habitants","B. 16396 Habitants","C. 16963 Habitants","D. 16369 Habitants"],[1],"Pmoy = (Pd + Pf) / 2 = (16109 + 16685) / 2 = 16397 habitants (proposition la plus proche : 16396).",null,"Q43"),
M("Quel est le Taux d'accouchement assiste du CSR de GBANGBEUGOUINE en 2024 ?",["A. 11,43%","B. 11,34%","C. 11,14%","D. 11,13%"],[1],"TAA = (Nbre de femmes enceintes ayant été assistée pdt l'accchment par un professionnel de santé ou par une accoucheuse traditionnelle) / (Nbre d'accouchements attendus) × 100 = (80 / 705) × 100 = 11,34 %.",null,"Q44"),
M("Quel est le Taux d'incidence des maladies diarrhéiques du CSR de GBANGBEUGOUINE en 2024 ?",["A. 0,06%","B. 0,03%","C. 0,36%","D. 0,63%"],[3],"TI = (Nouveau cas / Pmoy) × 100. Nbre de cas = 320 ; anciens = 2/3 × 320 ; nouveau cas = 320 − ((2/3) × 320) = 107 ; TI = (107 / 16397) × 100 = 0,65 %. La proposition la proposition la plus proche du résultat est retenue.",null,"Q45"),
M("Quel est le Taux de mortalité infantile du CSR de GBANGBEUGOUINE en 2024 ?",["A. 25%o.","B. 2,5%o.","C. 26% o.","D. 2,6%o."],[0],"TMI = ((Décès des enfants de 0 à 11mois) / NV) × 1000 = (3 / 120) × 1000 = 25 ‰.",null,"Q46"),
M("Quel est le Taux de mortalité maternelle du CSR de GBANGBEUGOUINE en 2024 ?",["A. 5400 décès maternels pour 100000 naissances vivantes","B. 5000 décès maternels pour 100000 naissances vivantes","C. 5050 décès maternels pour 100000 naissances vivantes","D. 5200 décès maternels pour 100000 naissances vivantes"],[1],"TMM = ((Décès de femmes pdt la grossesse, l'accouchement et 42jrs après accouchement, ni accidentel, ni fortuit) / NV) × 100000 = (6 / 120) × 100000 = 5000.",null,"Q47")
]}
);

